export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/manifest.json") {
      return new Response("{\n  \"name\": \"\u0627\u0644\u062f\u0634\u0627\u0634 \u0627\u0633\u062a\u0648\u0631 \u2014 \u0634\u062d\u0646 SuperLive\",\n  \"short_name\": \"\u0627\u0644\u062f\u0634\u0627\u0634 \u0627\u0633\u062a\u0648\u0631\",\n  \"description\": \"\u0645\u062a\u062c\u0631 \u0627\u0644\u062f\u0634\u0627\u0634 \u0627\u0633\u062a\u0648\u0631 \u0644\u0634\u062d\u0646 \u0643\u0648\u064a\u0646\u0632 SuperLive \u0648\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062d\u0641\u0638\u0629 \u0648\u0627\u0644\u0637\u0644\u0628\u0627\u062a\",\n  \"start_url\": \"./index.html\",\n  \"scope\": \"./\",\n  \"display\": \"standalone\",\n  \"orientation\": \"portrait\",\n  \"background_color\": \"#0d0e12\",\n  \"theme_color\": \"#0d0e12\",\n  \"dir\": \"rtl\",\n  \"lang\": \"ar\",\n  \"icons\": [\n    {\n      \"src\": \"icon.svg\",\n      \"sizes\": \"192x192 512x512\",\n      \"type\": \"image/svg+xml\",\n      \"purpose\": \"any maskable\"\n    }\n  ]\n}", {
        headers: { "content-type": "application/manifest+json; charset=utf-8" },
      });
    }
    if (url.pathname === "/icon.svg") {
      return new Response("<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\">\n  <defs>\n    <linearGradient id=\"bg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#171921\"/>\n      <stop offset=\"100%\" stop-color=\"#0b0c10\"/>\n    </linearGradient>\n    <linearGradient id=\"gold\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#f0c986\"/>\n      <stop offset=\"100%\" stop-color=\"#c49144\"/>\n    </linearGradient>\n  </defs>\n  <rect width=\"512\" height=\"512\" rx=\"112\" fill=\"url(#bg)\"/>\n  <rect x=\"24\" y=\"24\" width=\"464\" height=\"464\" rx=\"92\" fill=\"none\" stroke=\"url(#gold)\" stroke-width=\"6\" opacity=\"0.55\"/>\n  <text x=\"256\" y=\"295\" text-anchor=\"middle\" font-family=\"Cairo, Arial, sans-serif\" font-size=\"220\" font-weight=\"900\" fill=\"url(#gold)\">\u062f</text>\n  <text x=\"256\" y=\"388\" text-anchor=\"middle\" font-family=\"Cairo, Arial, sans-serif\" font-size=\"52\" font-weight=\"800\" fill=\"#f4f2ed\">\u0627\u0644\u062f\u0634\u0627\u0634 \u0627\u0633\u062a\u0648\u0631</text>\n</svg>\n", {
        headers: { "content-type": "image/svg+xml; charset=utf-8" },
      });
    }
    if (url.pathname === "/sw.js") {
      return new Response("const CACHE_NAME = \"eldashash-app-v10\";\nconst ASSETS = [\n  \"./\",\n  \"./index.html\",\n  \"./admin.html\",\n  \"./manifest.json\",\n  \"./icon.svg\"\n];\n\nself.addEventListener(\"install\", event => {\n  event.waitUntil(\n    caches.open(CACHE_NAME).then(cache => cache.addAll(ASSETS)).catch(() => {})\n  );\n  self.skipWaiting();\n});\n\nself.addEventListener(\"activate\", event => {\n  event.waitUntil(\n    caches.keys().then(keys =>\n      Promise.all(keys.filter(k => k !== CACHE_NAME).map(k => caches.delete(k)))\n    )\n  );\n  self.clients.claim();\n});\n\nself.addEventListener(\"fetch\", event => {\n  if (event.request.method !== \"GET\") return;\n  event.respondWith(\n    fetch(event.request).catch(() => caches.match(event.request))\n  );\n});\n", {
        headers: { "content-type": "application/javascript; charset=utf-8" },
      });
    }
    if (url.pathname.startsWith("/admin")) {
      return new Response('<!doctype html>\n<html lang="ar" dir="rtl">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>مركز تحكم الإدارة — الدشاش استور</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&display=swap" rel="stylesheet">\n<style>\n:root{\n  --bg:#0d0e12;--surface:#14161c;--surface-2:#1b1e27;--surface-3:#232734;\n  --ink:#f4f2ed;--ink-soft:#c8c3b8;--muted:#8b8982;\n  --brass:#d4a359;--brass-bright:#e8be7a;--brass-soft:rgba(212,163,89,.13);\n  --emerald:#28a774;--emerald-soft:rgba(40,167,116,.14);\n  --line:rgba(244,242,237,.09);--line-strong:rgba(212,163,89,.35);\n  --danger:#d9534f;\n}\n*{box-sizing:border-box}\nbody{margin:0;font-family:\'Cairo\',Tahoma,Arial,sans-serif;background:var(--bg);color:var(--ink);min-height:100vh}\nbutton,input,select{font:inherit}\nbutton{cursor:pointer;transition:.16s ease}\nbutton:disabled{opacity:.45;cursor:not-allowed}\n\n/* Admin Login Gate */\n#adminAuthScreen{\n  min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;\n}\n.auth-card{\n  width:min(420px,100%);\n  background:var(--surface);border:1px solid var(--line);\n  border-radius:18px;padding:26px 22px;\n}\n.field{margin-bottom:13px}\n.field label{display:block;font-size:12.5px;font-weight:700;color:var(--ink-soft);margin-bottom:6px}\n.field input{width:100%;padding:10px 13px;border-radius:10px;border:1px solid var(--line);background:var(--bg);color:var(--ink)}\n.field input:focus{outline:none;border-color:var(--brass)}\n.alert-box{padding:11px 13px;border-radius:10px;font-size:12.5px;line-height:1.65;margin-top:12px;font-weight:700}\n.alert-err{background:rgba(217,83,79,.13);border:1px solid rgba(217,83,79,.35);color:#f3a6a3}\n.alert-ok{background:var(--emerald-soft);border:1px solid rgba(40,167,116,.35);color:#78e0b5}\n\n/* Layout */\n.layout{display:none;grid-template-columns:240px 1fr;min-height:100vh}\n.layout.show{display:grid}\n\naside{background:var(--surface);border-left:1px solid var(--line);padding:22px 16px;display:flex;flex-direction:column;justify-content:space-between;position:sticky;top:0;height:100vh}\n.brand{display:flex;align-items:center;gap:10px;font-weight:900;font-size:17px;padding:4px 8px 16px;border-bottom:1px solid var(--line);margin-bottom:14px}\n.mono{width:32px;height:32px;border-radius:8px;background:var(--brass-soft);border:1px solid var(--line-strong);color:var(--brass-bright);display:grid;place-items:center;font-weight:900}\n.nav-menu{display:grid;gap:4px}\n.nav-item{\n  width:100%;text-align:right;border:1px solid transparent;background:transparent;\n  color:var(--muted);padding:10px 12px;border-radius:10px;font-weight:800;font-size:13.5px;\n  display:flex;align-items:center;justify-content:space-between;\n}\n.nav-item:hover{color:var(--ink);background:var(--surface-2)}\n.nav-item.active{color:var(--ink);background:var(--surface-2);border-color:var(--line-strong)}\n.cnt{font-size:11px;padding:1px 7px;border-radius:99px;background:var(--bg);color:var(--brass-bright);font-weight:800}\n\nmain{padding:24px 28px 60px;max-width:1260px;width:100%}\n.topbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:22px}\n.topbar h1{margin:0;font-size:22px;font-weight:900}\n.muted{color:var(--muted);font-size:12.5px}\n\n.btn{border:1px solid var(--line);background:var(--surface-2);color:var(--ink);padding:8px 14px;border-radius:9px;font-weight:800;font-size:12.5px;display:inline-flex;align-items:center;justify-content:center;gap:6px;text-decoration:none}\n.btn:hover:not(:disabled){border-color:var(--line-strong);background:var(--surface-3)}\n.btn.brass{background:var(--brass);color:#11100d;border-color:var(--brass)}\n.btn.brass:hover:not(:disabled){background:var(--brass-bright)}\n.btn.ok{background:var(--emerald-soft);color:#78e0b5;border-color:rgba(40,167,116,.35)}\n.btn.bad{background:rgba(217,83,79,.12);color:#f3a6a3;border-color:rgba(217,83,79,.32)}\n.btn.sm{padding:6px 10px;font-size:12px}\n\n.kpi-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px}\n.kpi{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px}\n.kpi .val{font-size:24px;font-weight:900;color:var(--brass-bright);margin-top:4px}\n\n.panel{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:18px;margin-bottom:16px}\n.panel-hdr{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:14px}\n.panel-hdr h3{margin:0;font-size:16.5px;font-weight:900}\n\n.row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:13px 0;border-bottom:1px solid var(--line)}\n.row:last-child{border-bottom:0}\n\ninput,select{background:var(--bg);border:1px solid var(--line);color:var(--ink);padding:8px 11px;border-radius:9px;font-size:13px}\ninput:focus,select:focus{outline:none;border-color:var(--brass)}\n\n.badge{display:inline-block;padding:3px 9px;border-radius:7px;font-size:11.5px;font-weight:800}\n.b-pending{background:var(--brass-soft);color:var(--brass-bright)}\n.b-paid{background:rgba(56,189,248,.14);color:#7dd3fc}\n.b-shipped,.b-approved{background:var(--emerald-soft);color:#78e0b5}\n.b-rejected{background:rgba(217,83,79,.13);color:#f3a6a3}\n\n.toast{position:fixed;bottom:20px;left:20px;background:var(--surface-2);border:1px solid var(--line-strong);color:var(--ink);padding:11px 16px;border-radius:10px;font-weight:800;font-size:13px;z-index:120}\n\n@media(max-width:920px){\n  .layout.show{grid-template-columns:1fr}\n  aside{position:static;height:auto;border-left:0;border-bottom:1px solid var(--line)}\n  .nav-menu{grid-template-columns:repeat(2,1fr)}\n  .kpi-grid{grid-template-columns:repeat(2,1fr)}\n}\n</style>\n<link rel="manifest" href="manifest.json">\n<meta name="theme-color" content="#0d0e12">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n<meta name="apple-mobile-web-app-title" content="الدشاش استور">\n<link rel="apple-touch-icon" href="icon.svg">\n<script>\nif ("serviceWorker" in navigator) {\n  window.addEventListener("load", () => {\n    navigator.serviceWorker.register("./sw.js").catch(() => {});\n  });\n}\n</script>\n</head>\n<body>\n\n<!-- ================= ADMIN LOGIN SCREEN ================= -->\n<section id="adminAuthScreen">\n  <div class="auth-card">\n    <div class="brand" style="padding-left:0;padding-right:0"><span class="mono">د</span> دخول لوحة الإدارة</div>\n    <p class="muted" style="margin:0 0 16px">سجّل دخولك بحساب الإدارة للوصول إلى الطلبات والمحافظ والباقات.</p>\n\n    <form id="adminLoginForm">\n      <div class="field">\n        <label for="admEmail">البريد الإلكتروني</label>\n        <input id="admEmail" type="email" required autocomplete="email" dir="ltr" placeholder="admin@example.com">\n      </div>\n      <div class="field">\n        <label for="admPass">كلمة المرور</label>\n        <input id="admPass" type="password" required autocomplete="current-password" dir="ltr" placeholder="••••••••">\n      </div>\n      <button type="submit" class="btn brass" id="admLoginBtn" style="width:100%;padding:10px">دخول لوحة الإدارة</button>\n      <button type="button" class="btn" id="admOtpBtn" style="width:100%;padding:9px;margin-top:8px" onclick="sendAdminOtp()">إرسال كود OTP (6 أرقام)</button>\n    </form>\n\n    <div id="adminOtpBox" style="display:none;margin-top:12px">\n      <div class="field">\n        <label for="admOtpCode">رمز التحقق (6 أرقام)</label>\n        <input id="admOtpCode" inputmode="numeric" maxlength="6" dir="ltr" style="text-align:center;font-size:20px;font-weight:900;letter-spacing:6px" placeholder="------">\n      </div>\n      <button type="button" class="btn brass" style="width:100%;padding:10px" onclick="verifyAdminOtp()">تأكيد الكود والدخول</button>\n    </div>\n\n    <div id="admAuthMsg" style="display:none"></div>\n    <div style="margin-top:14px;text-align:center">\n      <a class="muted" href="index.html" style="text-decoration:none">← العودة إلى المتجر</a>\n    </div>\n  </div>\n</section>\n\n<!-- ================= ADMIN DASHBOARD ================= -->\n<div class="layout" id="adminLayout">\n  <aside>\n    <div>\n      <div class="brand"><span class="mono">د</span> لوحة الإدارة</div>\n      <div class="muted" id="admSessionEmail" style="direction:ltr;text-align:right;margin-bottom:12px;word-break:break-all"></div>\n      <div class="nav-menu">\n        <button type="button" class="nav-item active" data-sec="overview" onclick="switchAdminSec(\'overview\')">نظرة عامة</button>\n        <button type="button" class="nav-item" data-sec="orders" onclick="switchAdminSec(\'orders\')">الطلبات <span class="cnt" id="cntOrders">0</span></button>\n        <button type="button" class="nav-item" data-sec="deposits" onclick="switchAdminSec(\'deposits\')">المحافظ والإيداع <span class="cnt" id="cntDeposits">0</span></button>\n        <button type="button" class="nav-item" data-sec="packages" onclick="switchAdminSec(\'packages\')">الباقات <span class="cnt" id="cntPkgs">0</span></button>\n        <button type="button" class="nav-item" data-sec="channels" onclick="switchAdminSec(\'channels\')">حسابات الدفع</button>\n      </div>\n    </div>\n    <div style="display:grid;gap:8px;margin-top:20px">\n      <a class="btn brass" href="index.html">فتح المتجر</a>\n      <button type="button" class="btn sm" onclick="refreshAll()">تحديث البيانات</button>\n      <button type="button" class="btn bad sm" onclick="adminLogout()">تسجيل خروج</button>\n    </div>\n  </aside>\n\n  <main>\n    <div class="topbar">\n      <div>\n        <h1 id="secTitle">نظرة عامة</h1>\n        <div class="muted">إدارة الطلبات، أرصدة المحافظ، الباقات، وحسابات التحويل</div>\n      </div>\n      <div style="display:flex;gap:8px;flex-wrap:wrap">\n        <button type="button" class="btn sm" onclick="refreshAll()">تحديث الآن</button>\n      </div>\n    </div>\n\n    <!-- SECTION 1: OVERVIEW -->\n    <div id="sec-overview">\n      <div class="kpi-grid">\n        <div class="kpi"><div class="muted">إجمالي الطلبات</div><div class="val" id="kpiOrders">0</div></div>\n        <div class="kpi"><div class="muted">طلبات قيد المراجعة</div><div class="val" id="kpiPending">0</div></div>\n        <div class="kpi"><div class="muted">إيداعات بانتظار الرصيد</div><div class="val" id="kpiDeposits">0</div></div>\n        <div class="kpi"><div class="muted">إجمالي مبالغ الطلبات</div><div class="val" id="kpiRevenue">0 ج.م</div></div>\n      </div>\n\n      <div class="panel">\n        <div class="panel-hdr"><h3>إدارة رصيد مستخدم مباشرة (إضافة / سحب)</h3></div>\n        <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">\n          <input id="quickUid" dir="ltr" placeholder="User UUID" style="flex:2;min-width:240px">\n          <input id="quickAmt" type="number" min="1" step="0.01" placeholder="المبلغ (ج.م)" style="width:140px">\n          <input id="quickNote" placeholder="سبب الإضافة أو السحب / ملاحظة" style="flex:1;min-width:170px">\n          <button type="button" class="btn brass" onclick="quickAddCredit()">إضافة الرصيد</button>\n          <button type="button" class="btn bad" onclick="quickWithdrawCredit()">سحب الرصيد</button>\n        </div>\n      </div>\n    </div>\n\n    <!-- SECTION 2: ORDERS -->\n    <div id="sec-orders" style="display:none">\n      <div class="panel">\n        <div class="panel-hdr">\n          <h3>طلبات الشحن</h3>\n          <div style="display:flex;gap:8px;flex-wrap:wrap">\n            <select id="orderStatusFilter" onchange="renderOrders()">\n              <option value="all">كل الحالات</option>\n              <option value="pending">قيد المراجعة</option>\n              <option value="paid">مؤكد</option>\n              <option value="shipped">تم الشحن</option>\n              <option value="rejected">مرفوض</option>\n            </select>\n            <input id="orderSearch" placeholder="بحث بالـ ID أو الاسم أو الهاتف..." oninput="renderOrders()">\n          </div>\n        </div>\n        <div id="ordersBox">جاري التحميل...</div>\n      </div>\n    </div>\n\n    <!-- SECTION 3: DEPOSITS & WALLETS -->\n    <div id="sec-deposits" style="display:none">\n      <div class="panel">\n        <div class="panel-hdr"><h3>تزويد أو سحب رصيد مستخدم</h3></div>\n        <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">\n          <input id="depManualUid" dir="ltr" placeholder="User UUID" style="flex:2;min-width:240px">\n          <input id="depManualAmt" type="number" min="1" step="0.01" placeholder="المبلغ (ج.م)" style="width:140px">\n          <input id="depManualNote" placeholder="ملاحظة" style="flex:1;min-width:160px">\n          <button type="button" class="btn brass" onclick="manualCreditFromDepTab()">تزويد الرصيد</button>\n          <button type="button" class="btn bad" onclick="manualWithdrawFromDepTab()">سحب الرصيد</button>\n        </div>\n      </div>\n\n      <div class="panel">\n        <div class="panel-hdr"><h3>أرصدة محافظ العملاء</h3></div>\n        <div id="walletsBox">جاري التحميل...</div>\n      </div>\n\n      <div class="panel">\n        <div class="panel-hdr"><h3>طلبات إيداع المحافظ</h3></div>\n        <div id="depositsBox">جاري التحميل...</div>\n      </div>\n    </div>\n\n    <!-- SECTION 4: PACKAGES -->\n    <div id="sec-packages" style="display:none">\n      <div class="panel">\n        <div class="panel-hdr"><h3>إضافة باقة جديدة</h3></div>\n        <form id="addPkgForm" style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">\n          <input id="newPkgCoins" type="number" min="1" step="1" required placeholder="عدد الكوينز" style="width:150px">\n          <input id="newPkgPrice" type="number" min="1" step="0.01" required placeholder="السعر (ج.م)" style="width:150px">\n          <select id="newPkgTier">\n            <option value="offer1">العرض الأول</option>\n            <option value="offer2">العرض الثاني</option>\n            <option value="offer3">العرض الثالث</option>\n          </select>\n          <button type="submit" class="btn brass">إضافة الباقة</button>\n        </form>\n      </div>\n\n      <div class="panel">\n        <div class="panel-hdr"><h3>الباقات الحالية</h3></div>\n        <div id="packagesBox">جاري التحميل...</div>\n      </div>\n    </div>\n\n    <!-- SECTION 5: PAYMENT CHANNELS -->\n    <div id="sec-channels" style="display:none">\n      <div class="panel">\n        <div class="panel-hdr"><h3>حسابات التحويل في المتجر</h3></div>\n        <div id="channelsEditorBox"></div>\n        <div style="display:flex;gap:8px;margin-top:12px">\n          <button type="button" class="btn brass" onclick="saveChannels()">حفظ الحسابات</button>\n          <button type="button" class="btn" onclick="resetChannels()">استعادة الافتراضي</button>\n        </div>\n      </div>\n    </div>\n  </main>\n</div>\n\n<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.min.js"></script>\n<script>\nconst SUPABASE_URL = "https://etdegfytfcfwuorexctj.supabase.co";\nconst SUPABASE_KEY = "sb_publishable_NP_1OLXEN0_f398DthKnGA_725B_IMf";\nconst PROOFS_BUCKET = "payment-proofs";\n// ضع بريدك أو بريد الأدمن هنا داخل المصفوفة (مثال: ["ayman@example.com"])\nconst ADMIN_EMAILS = [\n  "admin@eldashash.com"\n];\n\nconst sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY);\n\nconst DEFAULT_CHANNELS = [\n  { label: "إنستاباي (InstaPay)", number: "01119409694" },\n  { label: "فودافون كاش (Vodafone Cash)", number: "01011496149" }\n];\n\nlet ordersData = [];\nlet depositsData = [];\nlet packagesData = [];\n\nconst fmt = n => Number(n || 0).toLocaleString("en-US");\nconst esc = s => String(s ?? "").replace(/[&<>"\']/g, m => ({ "&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;","\'":"&#39;" }[m]));\n\nfunction toast(msg) {\n  const d = document.createElement("div");\n  d.className = "toast";\n  d.textContent = msg;\n  document.body.appendChild(d);\n  setTimeout(() => d.remove(), 2700);\n}\n\nfunction showAdmMsg(msg, ok = false) {\n  const el = document.getElementById("admAuthMsg");\n  el.style.display = "block";\n  el.className = ok ? "alert-box alert-ok" : "alert-box alert-err";\n  el.textContent = msg;\n}\n\nasync function isAllowedAdmin(user) {\n  if (!user || !user.email) return false;\n  const emailLower = String(user.email).trim().toLowerCase();\n  if (user.app_metadata && user.app_metadata.role === "admin") return true;\n\n  const list = ADMIN_EMAILS.map(x => String(x || "").trim().toLowerCase()).filter(Boolean);\n  if (list.includes(emailLower)) return true;\n\n  try {\n    const { data } = await sb.from("admin_users").select("email").ilike("email", emailLower).maybeSingle();\n    if (data && data.email) return true;\n  } catch {}\n\n  return false;\n}\n\nasync function checkAdminSession() {\n  const { data: { session } } = await sb.auth.getSession();\n  if (session && session.user && await isAllowedAdmin(session.user)) {\n    document.getElementById("adminAuthScreen").style.display = "none";\n    document.getElementById("adminLayout").classList.add("show");\n    document.getElementById("admSessionEmail").textContent = session.user.email || "";\n    await refreshAll();\n  } else {\n    document.getElementById("adminAuthScreen").style.display = "flex";\n    document.getElementById("adminLayout").classList.remove("show");\n  }\n}\n\ndocument.getElementById("adminLoginForm").addEventListener("submit", async e => {\n  e.preventDefault();\n  document.getElementById("admAuthMsg").style.display = "none";\n  const btn = document.getElementById("admLoginBtn");\n  btn.disabled = true;\n  try {\n    const email = document.getElementById("admEmail").value.trim().toLowerCase();\n    const password = document.getElementById("admPass").value;\n    const { data, error } = await sb.auth.signInWithPassword({ email, password });\n    if (error) { showAdmMsg(error.message); return; }\n    if (!(await isAllowedAdmin(data.user))) {\n      await sb.auth.signOut();\n      showAdmMsg("هذا البريد غير مصرّح له بدخول لوحة الإدارة.");\n      return;\n    }\n    await checkAdminSession();\n  } catch (err) {\n    showAdmMsg(err?.message || "تعذر تسجيل الدخول.");\n  } finally {\n    btn.disabled = false;\n  }\n});\n\nasync function sendAdminOtp() {\n  document.getElementById("admAuthMsg").style.display = "none";\n  const email = document.getElementById("admEmail").value.trim().toLowerCase();\n  if (!email) { showAdmMsg("اكتب البريد الإلكتروني أولاً."); return; }\n  if (!(await isAllowedAdmin({ email }))) { showAdmMsg("هذا البريد غير مصرّح له بدخول لوحة الإدارة."); return; }\n  const { error } = await sb.auth.signInWithOtp({ email, options: { shouldCreateUser: false } });\n  if (error) { showAdmMsg(error.message); return; }\n  document.getElementById("adminOtpBox").style.display = "block";\n  showAdmMsg("تم إرسال كود OTP (6 أرقام) إلى بريدك الإلكتروني.", true);\n}\n\nasync function verifyAdminOtp() {\n  const email = document.getElementById("admEmail").value.trim().toLowerCase();\n  const token = document.getElementById("admOtpCode").value.trim();\n  if (!email || !/^\\d{6}$/.test(token)) { showAdmMsg("أدخل الكود المكوّن من 6 أرقام."); return; }\n  const { data, error } = await sb.auth.verifyOtp({ email, token, type: "email" });\n  if (error) { showAdmMsg(error.message); return; }\n  if (!(await isAllowedAdmin(data.user))) {\n    await sb.auth.signOut();\n    showAdmMsg("هذا البريد غير مصرّح له بدخول لوحة الإدارة.");\n    return;\n  }\n  await checkAdminSession();\n}\n\nasync function adminLogout() {\n  await sb.auth.signOut();\n  await checkAdminSession();\n}\n\nfunction switchAdminSec(sec) {\n  const titles = {\n    overview: "نظرة عامة",\n    orders: "الطلبات",\n    deposits: "المحافظ والإيداع",\n    packages: "الباقات",\n    channels: "حسابات الدفع"\n  };\n  document.getElementById("secTitle").textContent = titles[sec] || "لوحة الإدارة";\n  ["overview", "orders", "deposits", "packages", "channels"].forEach(k => {\n    const el = document.getElementById("sec-" + k);\n    if (el) el.style.display = (k === sec) ? "block" : "none";\n  });\n  document.querySelectorAll(".nav-item").forEach(b => b.classList.toggle("active", b.dataset.sec === sec));\n}\n\nasync function viewProof(path) {\n  if (!path || path === "wallet_balance") { toast("مدفوع من رصيد المحفظة"); return; }\n  const { data, error } = await sb.storage.from(PROOFS_BUCKET).createSignedUrl(path, 120);\n  if (error || !data?.signedUrl) { toast("تعذر فتح الإيصال"); return; }\n  window.open(data.signedUrl, "_blank");\n}\n\nasync function addBalance(uid, amt, note, depId = null) {\n  if (!uid || !amt || Number(amt) <= 0) { toast("أدخل User ID ومبلغاً صحيحاً"); return; }\n  const { data: newBal, error } = await sb.rpc("admin_add_wallet_balance", {\n    target_user_id: uid.trim(),\n    add_amount: Number(amt),\n    note_text: note || "إضافة رصيد من الإدارة",\n    deposit_id: depId\n  });\n  if (error) { toast("خطأ: " + error.message); return; }\n  toast(`تمت الإضافة — الرصيد الحالي: ${Number(newBal).toFixed(2)} ج.م`);\n  await loadDeposits();\n}\n\nasync function quickAddCredit() {\n  await addBalance(\n    document.getElementById("quickUid").value,\n    document.getElementById("quickAmt").value,\n    document.getElementById("quickNote").value\n  );\n}\n\nasync function manualCreditFromDepTab() {\n  await addBalance(\n    document.getElementById("depManualUid").value,\n    document.getElementById("depManualAmt").value,\n    document.getElementById("depManualNote").value\n  );\n}\n\nasync function updateOrderStatus(orderId, status) {\n  const noteEl = document.getElementById("note_" + orderId);\n  const noteVal = noteEl ? noteEl.value.trim() : null;\n  const payload = { status };\n  if (noteVal) payload.admin_note = noteVal;\n  const { error } = await sb.from("orders").update(payload).eq("id", orderId);\n  if (error) { toast("تعذر التحديث: " + error.message); return; }\n  toast("تم تحديث حالة الطلب");\n  await loadOrders();\n}\n\nfunction renderOrders() {\n  const st = document.getElementById("orderStatusFilter").value;\n  const q = (document.getElementById("orderSearch").value || "").trim().toLowerCase();\n  const box = document.getElementById("ordersBox");\n\n  const list = ordersData.filter(o => {\n    const okSt = st === "all" || o.status === st;\n    const okQ = !q ||\n      String(o.superlive_id || "").toLowerCase().includes(q) ||\n      String(o.customer_name || "").toLowerCase().includes(q) ||\n      String(o.phone || "").toLowerCase().includes(q) ||\n      String(o.id || "").toLowerCase().includes(q);\n    return okSt && okQ;\n  });\n\n  if (!list.length) { box.innerHTML = \'<div class="muted">لا توجد طلبات مطابقة.</div>\'; return; }\n\n  box.innerHTML = list.map(o => `\n    <div class="row">\n      <div>\n        <b>${fmt(o.coins)} كوين</b> — <span style="color:var(--brass-bright);font-weight:800">${fmt(o.package_price)} ج.م</span>\n        <span class="badge b-${o.status || "pending"}" style="margin-right:6px">${esc(o.status || "pending")}</span><br>\n        <span class="muted">العميل: ${esc(o.customer_name || "-")} · هاتف: <span dir="ltr">${esc(o.phone || "-")}</span> · ID: <b>${esc(o.superlive_id || "-")}</b></span><br>\n        <span class="muted">الدفع: ${esc(o.payment_method || "-")} · ${o.created_at ? new Date(o.created_at).toLocaleString("ar-EG") : ""}</span>\n      </div>\n      <div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap">\n        <button type="button" class="btn sm" onclick="viewProof(\'${esc(o.payment_proof || "")}\')">الإيصال</button>\n        <input id="note_${esc(o.id)}" value="${esc(o.admin_note || "")}" placeholder="ملاحظة" style="width:130px;padding:6px 9px">\n        <button type="button" class="btn ok sm" onclick="updateOrderStatus(\'${esc(o.id)}\',\'shipped\')">تم الشحن</button>\n        <button type="button" class="btn bad sm" onclick="updateOrderStatus(\'${esc(o.id)}\',\'rejected\')">رفض</button>\n      </div>\n    </div>\n  `).join("");\n}\n\nasync function loadOrders() {\n  const box = document.getElementById("ordersBox");\n  let res = await sb.from("orders").select("*").order("created_at", { ascending: false }).limit(150);\n  if (res.error) {\n    res = await sb.from("orders").select("*").limit(150);\n  }\n  if (res.error) {\n    box.innerHTML = `<div class="muted">تعذر جلب الطلبات: ${esc(res.error.message)}</div>`;\n    return;\n  }\n  ordersData = res.data || [];\n  document.getElementById("cntOrders").textContent = ordersData.length;\n  document.getElementById("kpiOrders").textContent = ordersData.length;\n  document.getElementById("kpiPending").textContent = ordersData.filter(x => x.status === "pending").length;\n  const sum = ordersData.filter(x => x.status !== "rejected").reduce((a, b) => a + Number(b.package_price || 0), 0);\n  document.getElementById("kpiRevenue").textContent = `${fmt(sum)} ج.م`;\n  renderOrders();\n}\n\nasync function rejectDeposit(depId) {\n  const { error } = await sb.from("wallet_deposits").update({ status: "rejected", reviewed_at: new Date().toISOString() }).eq("id", depId);\n  if (error) { toast(error.message); return; }\n  toast("تم رفض طلب الإيداع");\n  await loadDeposits();\n}\n\nasync function loadDeposits() {\n  const box = document.getElementById("depositsBox");\n  const { data, error } = await sb\n    .from("wallet_deposits")\n    .select("*")\n    .order("created_at", { ascending: false })\n    .limit(80);\n\n  if (error) { box.innerHTML = `<div class="muted">${esc(error.message)}</div>`; return; }\n  depositsData = data || [];\n  const pendingCount = depositsData.filter(d => d.status === "pending").length;\n  document.getElementById("cntDeposits").textContent = pendingCount;\n  document.getElementById("kpiDeposits").textContent = pendingCount;\n\n  if (!depositsData.length) { box.innerHTML = \'<div class="muted">لا توجد طلبات إيداع.</div>\'; return; }\n\n  box.innerHTML = depositsData.map(d => `\n    <div class="row">\n      <div>\n        <b>${Number(d.amount).toFixed(2)} ج.م</b> — <span class="muted">${esc(d.payment_method)}</span>\n        <span class="badge b-${d.status}" style="margin-right:6px">${esc(d.status)}</span><br>\n        <span class="muted">${esc(d.user_email || "-")} · UID: <span dir="ltr">${esc(d.user_id)}</span></span><br>\n        <span class="muted">${d.created_at ? new Date(d.created_at).toLocaleString("ar-EG") : ""}</span>\n      </div>\n      <div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap">\n        <button type="button" class="btn sm" onclick="viewProof(\'${esc(d.proof_path || "")}\')">الإيصال</button>\n        <input type="number" step="0.01" id="amt_${esc(d.id)}" value="${Number(d.amount)}" style="width:98px;padding:6px 8px">\n        <button type="button" class="btn brass sm" onclick="addBalance(\'${esc(d.user_id)}\', document.getElementById(\'amt_${esc(d.id)}\').value, \'اعتماد إيداع\', \'${esc(d.id)}\')">تزويد رصيد</button>\n        <button type="button" class="btn bad sm" onclick="withdrawBalance(\'${esc(d.user_id)}\', document.getElementById(\'amt_${esc(d.id)}\').value, \'سحب رصيد من الإدارة\')">سحب رصيد</button>\n        <button type="button" class="btn sm" onclick="rejectDeposit(\'${esc(d.id)}\')">رفض</button>\n      </div>\n    </div>\n  `).join("");\n}\n\nasync function loadPackages() {\n  const box = document.getElementById("packagesBox");\n  const { data, error } = await sb.from("packages").select("*").order("price_egp");\n  if (error) { box.innerHTML = `<div class="muted">${esc(error.message)}</div>`; return; }\n  packagesData = data || [];\n  document.getElementById("cntPkgs").textContent = packagesData.length;\n  if (!packagesData.length) { box.innerHTML = \'<div class="muted">لا توجد باقات في الجدول بعد.</div>\'; return; }\n\n  box.innerHTML = packagesData.map(p => `\n    <div class="row">\n      <div>\n        <b>${fmt(p.coins)} كوين</b> — <span style="color:var(--brass-bright);font-weight:800">${fmt(p.price_egp)} ج.م</span>\n        <span class="muted">(${esc(p.offer_group)} · ${p.active ? "نشطة" : "متوقفة"})</span>\n      </div>\n      <div style="display:flex;gap:7px">\n        <button type="button" class="btn sm" onclick="togglePkg(${p.id}, ${!p.active})">${p.active ? "إيقاف" : "تفعيل"}</button>\n        <button type="button" class="btn bad sm" onclick="deletePkg(${p.id})">حذف</button>\n      </div>\n    </div>\n  `).join("");\n}\n\ndocument.getElementById("addPkgForm").addEventListener("submit", async e => {\n  e.preventDefault();\n  const coins = Number(document.getElementById("newPkgCoins").value);\n  const price_egp = Number(document.getElementById("newPkgPrice").value);\n  const offer_group = document.getElementById("newPkgTier").value;\n  const { error } = await sb.from("packages").insert({ coins, price_egp, offer_group, active: true });\n  if (error) { toast(error.message); return; }\n  e.target.reset();\n  toast("تمت إضافة الباقة");\n  await loadPackages();\n});\n\nasync function togglePkg(id, active) {\n  const { error } = await sb.from("packages").update({ active }).eq("id", id);\n  if (error) { toast(error.message); return; }\n  await loadPackages();\n}\n\nasync function deletePkg(id) {\n  const { error } = await sb.from("packages").delete().eq("id", id);\n  if (error) { toast(error.message); return; }\n  toast("تم حذف الباقة");\n  await loadPackages();\n}\n\nfunction renderChannelsEditor() {\n  let chs = DEFAULT_CHANNELS;\n  try {\n    const saved = JSON.parse(localStorage.getItem("eldashash_channels_v1") || "null");\n    if (Array.isArray(saved) && saved.length) chs = saved;\n  } catch {}\n\n  document.getElementById("channelsEditorBox").innerHTML = chs.map((c, i) => `\n    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px">\n      <input id="chLabel_${i}" value="${esc(c.label)}" placeholder="اسم الوسيلة" style="flex:1;min-width:190px">\n      <input id="chNum_${i}" dir="ltr" value="${esc(c.number)}" placeholder="الرقم" style="flex:1;min-width:190px">\n    </div>\n  `).join("");\n}\n\nfunction saveChannels() {\n  const chs = [0, 1].map(i => ({\n    label: (document.getElementById("chLabel_" + i)?.value || "").trim(),\n    number: (document.getElementById("chNum_" + i)?.value || "").trim()\n  })).filter(x => x.label && x.number);\n  if (!chs.length) { toast("أدخل بيانات صحيحة"); return; }\n  localStorage.setItem("eldashash_channels_v1", JSON.stringify(chs));\n  toast("تم حفظ حسابات التحويل");\n}\n\nfunction resetChannels() {\n  localStorage.removeItem("eldashash_channels_v1");\n  renderChannelsEditor();\n  toast("تمت الاستعادة");\n}\n\n\nasync function withdrawBalance(uid, amt, note) {\n  if (!uid || !amt || Number(amt) <= 0) { toast("أدخل User ID ومبلغاً صحيحاً"); return; }\n  const { data: newBal, error } = await sb.rpc("admin_withdraw_wallet_balance", {\n    target_user_id: uid.trim(),\n    withdraw_amount: Number(amt),\n    note_text: note || "سحب رصيد بواسطة الإدارة"\n  });\n  if (error) { toast("خطأ: " + error.message); return; }\n  toast(`تم سحب ${Number(amt).toFixed(2)} ج.م — الرصيد المتبقي: ${Number(newBal).toFixed(2)} ج.م`);\n  await Promise.all([loadDeposits(), loadWallets()]);\n}\n\nasync function quickWithdrawCredit() {\n  await withdrawBalance(\n    document.getElementById("quickUid").value,\n    document.getElementById("quickAmt").value,\n    document.getElementById("quickNote").value || "سحب رصيد من الإدارة"\n  );\n}\n\nasync function manualWithdrawFromDepTab() {\n  await withdrawBalance(\n    document.getElementById("depManualUid").value,\n    document.getElementById("depManualAmt").value,\n    document.getElementById("depManualNote").value || "سحب رصيد من الإدارة"\n  );\n}\n\nasync function loadWallets() {\n  const box = document.getElementById("walletsBox");\n  if (!box) return;\n  const { data, error } = await sb.from("wallets").select("user_id,user_email,balance,updated_at").order("balance", { ascending: false }).limit(60);\n  if (error) { box.innerHTML = `<div class="muted">${esc(error.message)}</div>`; return; }\n  if (!data || !data.length) { box.innerHTML = \'<div class="muted">لا توجد محافظ مسجلة بعد.</div>\'; return; }\n\n  box.innerHTML = data.map(w => `\n    <div class="row">\n      <div>\n        <b>${esc(w.user_email || "مستخدم")}</b> — <span style="color:var(--brass-bright);font-weight:900">${Number(w.balance || 0).toFixed(2)} ج.م</span><br>\n        <span class="muted">UID: <span dir="ltr">${esc(w.user_id)}</span></span>\n      </div>\n      <div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap">\n        <input type="number" min="1" step="0.01" id="wamt_${esc(w.user_id)}" placeholder="مبلغ" style="width:95px;padding:6px 8px">\n        <button type="button" class="btn brass sm" onclick="addBalance(\'${esc(w.user_id)}\', document.getElementById(\'wamt_${esc(w.user_id)}\').value, \'إضافة رصيد من لوحة المحافظ\', null)">إضافة</button>\n        <button type="button" class="btn bad sm" onclick="withdrawBalance(\'${esc(w.user_id)}\', document.getElementById(\'wamt_${esc(w.user_id)}\').value, \'سحب رصيد من لوحة المحافظ\')">سحب رصيد</button>\n      </div>\n    </div>\n  `).join("");\n}\n\nasync function refreshAll() {\n  renderChannelsEditor();\n  await Promise.all([loadOrders(), loadDeposits(), loadWallets(), loadPackages()]);\n}\n\nwindow.addEventListener("load", checkAdminSession);\n</script>\n</body>\n</html>\n', {
        headers: { "content-type": "text/html; charset=utf-8" },
      });
    }
    return new Response('<!doctype html>\n<html lang="ar" dir="rtl">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<meta name="theme-color" content="#0d0e12">\n<title>الدشاش استور — منصة الشحن الرقمي</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">\n<style>\n:root{\n  --bg:#0d0e12;\n  --surface:#14161c;\n  --surface-2:#1b1e27;\n  --surface-3:#222632;\n  --ink:#f4f2ed;\n  --ink-soft:#c8c3b8;\n  --muted:#8b8982;\n  --brass:#d4a359;\n  --brass-bright:#e8be7a;\n  --brass-soft:rgba(212,163,89,.13);\n  --emerald:#28a774;\n  --emerald-soft:rgba(40,167,116,.14);\n  --line:rgba(244,242,237,.09);\n  --line-strong:rgba(212,163,89,.36);\n  --danger:#d9534f;\n  --radius-lg:20px;\n  --radius-md:14px;\n  --radius-sm:10px;\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{\n  margin:0;\n  font-family:\'Cairo\',Tahoma,Arial,sans-serif;\n  background:var(--bg);\n  color:var(--ink);\n  min-height:100vh;\n  -webkit-font-smoothing:antialiased;\n}\nbutton,input,textarea,select{font:inherit}\nbutton{cursor:pointer;transition:background-color .18s ease,border-color .18s ease,color .18s ease,transform .18s ease}\nbutton:disabled{opacity:.45;cursor:not-allowed}\n.wrap{width:min(1220px,calc(100% - 32px));margin:auto}\n\n/* Subtle architectural noise & warm top vignette */\nbody::before{\n  content:"";\n  position:fixed;inset:0;pointer-events:none;z-index:-1;\n  background:radial-gradient(900px 360px at 50% -60px, rgba(212,163,89,.08), transparent 70%);\n}\n\n/* Toast */\n.toast-box{position:fixed;bottom:22px;left:22px;z-index:130;display:flex;flex-direction:column;gap:8px;max-width:350px}\n.toast{\n  background:var(--surface-2);\n  border:1px solid var(--line-strong);\n  color:var(--ink);\n  padding:11px 16px;\n  border-radius:var(--radius-sm);\n  font-size:13px;font-weight:700;\n  box-shadow:0 14px 32px rgba(0,0,0,.55);\n}\n\n/* Buttons */\n.btn{\n  border:1px solid var(--line);\n  background:var(--surface-2);\n  color:var(--ink);\n  padding:10px 16px;\n  border-radius:var(--radius-sm);\n  font-weight:700;\n  font-size:13.5px;\n  display:inline-flex;align-items:center;justify-content:center;gap:8px;\n  text-decoration:none;\n}\n.btn:hover:not(:disabled){border-color:var(--line-strong);background:var(--surface-3)}\n.btn.brass{\n  background:var(--brass);\n  color:#11100d;\n  border-color:var(--brass);\n  font-weight:800;\n}\n.btn.brass:hover:not(:disabled){background:var(--brass-bright);border-color:var(--brass-bright)}\n.btn.ghost-brass{\n  background:var(--brass-soft);\n  color:var(--brass-bright);\n  border-color:rgba(212,163,89,.28);\n}\n.btn.ghost-brass:hover:not(:disabled){border-color:var(--brass)}\n.btn.danger-soft{\n  background:rgba(217,83,79,.1);\n  color:#f29b98;\n  border-color:rgba(217,83,79,.25);\n}\n.btn.sm{padding:7px 12px;font-size:12.5px;border-radius:9px}\n.icon-btn{width:38px;height:38px;padding:0;border-radius:10px;font-size:17px;position:relative}\n\n.muted{color:var(--muted);font-size:13px}\n.field{margin-bottom:14px}\n.field label{display:block;font-size:12.5px;font-weight:700;color:var(--ink-soft);margin-bottom:6px}\n.field input,.field textarea,.field select{\n  width:100%;\n  padding:11px 14px;\n  border-radius:var(--radius-sm);\n  border:1px solid var(--line);\n  background:var(--bg);\n  color:var(--ink);\n}\n.field input:focus,.field textarea:focus,.field select:focus{\n  outline:none;border-color:var(--brass);\n}\n\n.alert{padding:11px 14px;border-radius:var(--radius-sm);font-size:13px;line-height:1.65;margin-top:12px;font-weight:600}\n.alert.err{background:rgba(217,83,79,.12);border:1px solid rgba(217,83,79,.35);color:#f3a6a3}\n.alert.ok{background:var(--emerald-soft);border:1px solid rgba(40,167,116,.35);color:#78e0b5}\n\n/* ================= AUTH SCREEN ================= */\n#authScreen{min-height:100vh;display:grid;grid-template-columns:1.08fr .92fr}\n.auth-editorial{\n  padding:48px 52px;\n  display:flex;flex-direction:column;justify-content:space-between;\n  background:var(--surface);\n  border-left:1px solid var(--line);\n}\n.brand-mark{display:inline-flex;align-items:center;gap:12px;font-size:20px;font-weight:900;letter-spacing:-.2px;cursor:pointer}\n.brand-monogram{\n  width:36px;height:36px;border-radius:10px;\n  border:1px solid var(--line-strong);\n  background:var(--brass-soft);\n  color:var(--brass-bright);\n  display:grid;place-items:center;\n  font-weight:900;font-size:17px;\n}\n.auth-copy{max-width:500px}\n.eyebrow{\n  display:inline-flex;align-items:center;gap:8px;\n  font-size:12px;font-weight:800;letter-spacing:.4px;\n  color:var(--brass-bright);\n  margin-bottom:14px;\n}\n.eyebrow::before{content:"";width:18px;height:1px;background:var(--brass)}\n.auth-copy h1{font-size:clamp(30px,3.6vw,44px);line-height:1.2;margin:0 0 14px;font-weight:900}\n.auth-copy h1 span{color:var(--brass-bright)}\n.auth-copy p{color:var(--muted);line-height:1.85;margin:0 0 26px;font-size:14.5px}\n.auth-pillars{display:grid;gap:10px}\n.pillar-row{\n  display:flex;align-items:center;justify-content:space-between;\n  padding:13px 16px;border-radius:var(--radius-md);\n  border:1px solid var(--line);background:var(--bg);\n  font-size:13.5px;font-weight:600;color:var(--ink-soft);\n}\n.pillar-row span:last-child{color:var(--brass-bright);font-weight:800;font-size:12px}\n\n.auth-form-col{display:flex;align-items:center;justify-content:center;padding:28px 18px}\n.auth-box{\n  width:min(430px,100%);\n  background:var(--surface);\n  border:1px solid var(--line);\n  border-radius:var(--radius-lg);\n  padding:28px 24px;\n}\n.seg-tabs{\n  display:grid;grid-template-columns:1fr 1fr;gap:4px;\n  background:var(--bg);padding:4px;border-radius:11px;\n  border:1px solid var(--line);margin-bottom:20px;\n}\n.seg-btn{border:0;background:transparent;color:var(--muted);padding:9px;border-radius:8px;font-weight:800;font-size:13.5px}\n.seg-btn.active{background:var(--surface-2);color:var(--ink);border:1px solid var(--line-strong)}\n\n.otp-email-chip{\n  display:inline-block;background:var(--brass-soft);border:1px solid var(--line-strong);\n  color:var(--brass-bright);padding:5px 12px;border-radius:8px;\n  font-size:13px;font-weight:800;direction:ltr;margin-bottom:12px;\n}\n\n/* ================= TOP HEADER & TABS ================= */\nheader{\n  display:none;position:sticky;top:0;z-index:35;\n  background:rgba(13,14,18,.88);backdrop-filter:blur(14px);\n  border-bottom:1px solid var(--line);\n}\nheader.show{display:block}\n.nav-row{min-height:68px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}\n.nav-right{display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n\n.subnav{border-top:1px solid var(--line);background:var(--surface)}\n.subnav-inner{display:flex;align-items:center;gap:6px;overflow-x:auto;padding:8px 0}\n.tab-link{\n  border:1px solid transparent;background:transparent;color:var(--muted);\n  padding:8px 15px;border-radius:9px;font-weight:800;font-size:13px;\n  display:inline-flex;align-items:center;gap:8px;white-space:nowrap;\n}\n.tab-link:hover{color:var(--ink);background:var(--surface-2)}\n.tab-link.active{color:var(--ink);background:var(--surface-2);border-color:var(--line-strong)}\n.pill-tag{font-size:10.5px;font-weight:800;padding:2px 7px;border-radius:99px}\n.pill-tag.live{background:var(--emerald-soft);color:#6ee7b7}\n.pill-tag.soon{background:var(--brass-soft);color:var(--brass-bright)}\n\n/* ================= STOREFRONT CONTENT ================= */\n#shop{display:none;padding:28px 0 64px}\n#shop.show{display:block}\n\n.hero-card{\n  background:var(--surface);\n  border:1px solid var(--line);\n  border-radius:var(--radius-lg);\n  padding:32px;\n  display:flex;align-items:center;justify-content:space-between;gap:24px;\n  margin-bottom:28px;\n}\n.hero-card h1,.hero-card h2{margin:0 0 10px;font-size:clamp(25px,3.4vw,36px);font-weight:900;line-height:1.22}\n.hero-card h1 span,.hero-card h2 span{color:var(--brass-bright)}\n.hero-card p{margin:0;color:var(--muted);line-height:1.8;max-width:620px;font-size:14.5px}\n.hero-meta{\n  background:var(--bg);border:1px solid var(--line);\n  border-radius:var(--radius-md);padding:18px 22px;min-width:190px;text-align:center;\n}\n.hero-meta .big{font-size:22px;font-weight:900;color:var(--brass-bright)}\n\n.sec-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:26px 0 14px}\n.sec-head h3{margin:0;font-size:18px;font-weight:900}\n\n/* Programs Grid */\n.apps-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}\n.app-tile{\n  background:var(--surface);border:1px solid var(--line);\n  border-radius:var(--radius-lg);padding:22px;\n  display:flex;flex-direction:column;justify-content:space-between;gap:18px;\n}\n.app-tile.ready{border-color:rgba(212,163,89,.28)}\n.app-tile:hover{border-color:var(--line-strong)}\n.app-tile-top{display:flex;align-items:center;justify-content:space-between;gap:10px}\n.app-badge-icon{\n  width:46px;height:46px;border-radius:12px;\n  background:var(--bg);border:1px solid var(--line);\n  display:grid;place-items:center;font-size:22px;\n}\n.status-txt{font-size:11.5px;font-weight:800;padding:3px 10px;border-radius:99px}\n.status-txt.ready{background:var(--emerald-soft);color:#6ee7b7}\n.status-txt.soon{background:var(--brass-soft);color:var(--brass-bright)}\n.app-tile h4{margin:0 0 6px;font-size:18px;font-weight:800}\n.app-tile p{margin:0;color:var(--muted);font-size:13px;line-height:1.7}\n\n/* Steps */\n.steps-row{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:24px}\n.step-item{\n  background:var(--surface);border:1px solid var(--line);\n  border-radius:var(--radius-md);padding:15px 16px;\n  display:flex;align-items:center;gap:12px;\n}\n.step-idx{\n  width:30px;height:30px;border-radius:8px;\n  background:var(--brass-soft);color:var(--brass-bright);\n  font-weight:900;font-size:13.5px;display:grid;place-items:center;flex-shrink:0;\n}\n\n/* Payment Grid */\n.pay-row{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-bottom:24px}\n.pay-card{\n  background:var(--surface);border:1px solid var(--line);\n  border-radius:var(--radius-md);padding:18px 20px;\n  display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;\n}\n.pay-num{font-size:20px;font-weight:900;direction:ltr;color:var(--brass-bright);letter-spacing:.8px;margin-top:3px}\n\n/* Filter & Search */\n.filter-bar{\n  background:var(--surface);border:1px solid var(--line);\n  border-radius:var(--radius-md);padding:10px 12px;\n  display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;\n  margin-bottom:16px;\n}\n.tier-pills{display:flex;gap:6px;flex-wrap:wrap}\n.pill-btn{border:1px solid transparent;background:transparent;color:var(--muted);padding:7px 14px;border-radius:9px;font-weight:800;font-size:12.5px}\n.pill-btn:hover{color:var(--ink);background:var(--surface-2)}\n.pill-btn.active{background:var(--brass);color:#11100d}\n.search-box{background:var(--bg);border:1px solid var(--line);color:var(--ink);padding:8px 13px;border-radius:9px;min-width:230px}\n.search-box:focus{outline:none;border-color:var(--brass)}\n\n/* Packages */\n.pkg-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}\n.pkg-item{\n  background:var(--surface);border:1px solid var(--line);\n  border-radius:var(--radius-md);padding:18px;\n  display:flex;flex-direction:column;justify-content:space-between;gap:15px;\n}\n.pkg-item:hover{border-color:var(--line-strong);transform:translateY(-2px)}\n.pkg-item.featured-tier{border-color:rgba(212,163,89,.32)}\n.pkg-head{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.pkg-code{font-size:11px;font-weight:800;letter-spacing:.8px;color:var(--muted)}\n.pkg-tier{font-size:11px;font-weight:800;color:var(--brass-bright);background:var(--brass-soft);padding:2px 9px;border-radius:99px}\n.pkg-amount{font-size:22px;font-weight:900;color:var(--ink);margin:8px 0 2px}\n.pkg-price-line{\n  display:flex;align-items:center;justify-content:space-between;\n  padding:8px 11px;border-radius:9px;\n  background:var(--bg);border:1px solid var(--line);margin-bottom:10px;\n}\n.pkg-price-val{font-size:17px;font-weight:900;color:var(--brass-bright)}\n\n/* Wallet & Checkout helpers */\n.wallet-banner{\n  background:var(--bg);border:1px solid var(--line-strong);\n  border-radius:var(--radius-md);padding:18px;margin-bottom:16px;\n}\n.wallet-bal{font-size:28px;font-weight:900;color:var(--brass-bright);margin:4px 0}\n.choice-row{\n  display:flex;align-items:center;gap:10px;padding:10px 12px;\n  border:1px solid var(--line);border-radius:10px;margin-bottom:8px;\n  background:var(--bg);font-size:13px;font-weight:700;cursor:pointer;\n}\n.choice-row input{width:auto;margin:0;accent-color:var(--brass)}\n\n/* Modals */\n.modal-bg{\n  position:fixed;inset:0;background:rgba(6,7,10,.78);backdrop-filter:blur(6px);\n  z-index:70;display:none;align-items:center;justify-content:center;padding:16px;overflow:auto;\n}\n.modal-bg.open{display:flex}\n.modal-box{\n  background:var(--surface);border:1px solid var(--line);\n  border-radius:var(--radius-lg);width:min(540px,100%);\n  padding:22px;max-height:90vh;overflow:auto;\n}\n.modal-hdr{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-bottom:12px;margin-bottom:15px;border-bottom:1px solid var(--line)}\n.modal-hdr h3{margin:0;font-size:18px;font-weight:900}\n.x-btn{border:1px solid var(--line);background:var(--bg);color:var(--ink);width:32px;height:32px;border-radius:8px;font-weight:800}\n\n.list-row{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 0;border-bottom:1px solid var(--line)}\n.list-row:last-child{border-bottom:0}\n.st-badge{display:inline-block;padding:4px 10px;border-radius:8px;font-size:11.5px;font-weight:800}\n.st-pending{background:var(--brass-soft);color:var(--brass-bright)}\n.st-paid{background:rgba(56,189,248,.14);color:#7dd3fc}\n.st-shipped{background:var(--emerald-soft);color:#6ee7b7}\n.st-rejected{background:rgba(217,83,79,.14);color:#f3a6a3}\n.proof-thumb{display:none;max-width:100%;max-height:200px;border-radius:10px;margin-top:10px;border:1px solid var(--line)}\n\nfooter{display:none;border-top:1px solid var(--line);padding:20px 0;color:var(--muted);font-size:13px;background:var(--surface)}\nfooter.show{display:block}\n.foot-inner{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}\n\n@media(max-width:980px){\n  #authScreen{grid-template-columns:1fr}\n  .auth-editorial{display:none}\n  .apps-grid,.steps-row{grid-template-columns:1fr}\n  .pkg-grid{grid-template-columns:repeat(3,1fr)}\n}\n@media(max-width:640px){\n  .pkg-grid{grid-template-columns:repeat(2,1fr);gap:10px}\n  .pkg-item{padding:14px}\n  .pkg-amount{font-size:19px}\n  .pay-row{grid-template-columns:1fr}\n  .hero-card{flex-direction:column;align-items:flex-start;padding:22px}\n  .hero-meta{width:100%}\n}\n</style>\n<link rel="manifest" href="manifest.json">\n<meta name="theme-color" content="#0d0e12">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n<meta name="apple-mobile-web-app-title" content="الدشاش استور">\n<link rel="apple-touch-icon" href="icon.svg">\n<script>\nif ("serviceWorker" in navigator) {\n  window.addEventListener("load", () => {\n    navigator.serviceWorker.register("./sw.js").catch(() => {});\n  });\n}\n</script>\n</head>\n<body>\n\n<div class="toast-box" id="toastBox"></div>\n\n<!-- ================= AUTH ================= -->\n<section id="authScreen">\n  <div class="auth-editorial">\n    <div class="brand-mark"><span class="brand-monogram">د</span> الدشاش استور</div>\n    <div class="auth-copy">\n      <div class="eyebrow">وكالة الشحن الرقمي</div>\n      <h1>شحن مباشر وموثوق<br><span>لبرامجك وحساباتك</span></h1>\n      <p>سجّل دخولك بالبريد الإلكتروني وكود التحقق المكوّن من 6 أرقام لإدارة محفظتك، متابعة طلباتك، وشحن باقات SuperLive وغيرها من الأقسام.</p>\n      <div class="auth-pillars">\n        <div class="pillar-row"><span>شحن SuperLive بالـ ID</span><span>متاح الآن</span></div>\n        <div class="pillar-row"><span>محفظة رصيد وطلبات إيداع</span><span>مفعّلة</span></div>\n        <div class="pillar-row"><span>تحقق بالبريد الإلكتروني (OTP)</span><span>6 أرقام</span></div>\n      </div>\n    </div>\n    <div class="muted">الدشاش استور — جميع الحقوق محفوظة</div>\n  </div>\n\n  <div class="auth-form-col">\n    <div class="auth-box">\n      <div style="margin-bottom:16px">\n        <div style="font-size:20px;font-weight:900">تسجيل الدخول للمتجر</div>\n        <div class="muted">أدخل بريدك الإلكتروني للمتابعة أو إنشاء حساب</div>\n      </div>\n\n      <div class="seg-tabs" id="modeSwitch">\n        <button type="button" class="seg-btn active" id="btnTabLogin" onclick="switchAuthMode(\'login\')">دخول</button>\n        <button type="button" class="seg-btn" id="btnTabSignup" onclick="switchAuthMode(\'signup\')">حساب جديد</button>\n      </div>\n\n      <form id="loginForm">\n        <div class="field">\n          <label for="lEmail">البريد الإلكتروني</label>\n          <input id="lEmail" type="email" required autocomplete="email" dir="ltr" placeholder="name@example.com">\n        </div>\n        <div class="field">\n          <label for="lPass">كلمة المرور</label>\n          <input id="lPass" type="password" required autocomplete="current-password" dir="ltr" placeholder="••••••••">\n        </div>\n        <button type="submit" class="btn brass" id="lSubmit" style="width:100%;padding:11px">دخول بكلمة المرور</button>\n        <button type="button" class="btn" id="btnOtpLogin" style="width:100%;padding:10px;margin-top:8px" onclick="startEmailOtpLogin()">دخول سريع بكود OTP (6 أرقام)</button>\n      </form>\n\n      <form id="signupForm" style="display:none">\n        <div class="field">\n          <label for="sName">الاسم بالكامل</label>\n          <input id="sName" required autocomplete="name" placeholder="الاسم">\n        </div>\n        <div class="field">\n          <label for="sEmail">البريد الإلكتروني</label>\n          <input id="sEmail" type="email" required autocomplete="email" dir="ltr" placeholder="name@example.com">\n        </div>\n        <div class="field">\n          <label for="sPass">كلمة المرور</label>\n          <input id="sPass" type="password" minlength="6" required autocomplete="new-password" dir="ltr" placeholder="6 أحرف على الأقل">\n        </div>\n        <div class="field">\n          <label for="sPass2">تأكيد كلمة المرور</label>\n          <input id="sPass2" type="password" minlength="6" required autocomplete="new-password" dir="ltr" placeholder="أعد كتابة كلمة المرور">\n        </div>\n        <button type="submit" class="btn brass" id="sSubmit" style="width:100%;padding:11px">إنشاء الحساب وإرسال الرمز</button>\n      </form>\n\n      <div id="otpSection" style="display:none">\n        <div id="otpTargetEmail" class="otp-email-chip"></div>\n        <div class="field">\n          <label for="otpInput">رمز التحقق (6 أرقام)</label>\n          <input id="otpInput" inputmode="numeric" maxlength="6" pattern="\\d{6}" autocomplete="one-time-code" dir="ltr" style="text-align:center;font-size:23px;font-weight:900;letter-spacing:8px;font-family:monospace" placeholder="------">\n        </div>\n        <button type="button" class="btn brass" id="btnConfirmOtp" style="width:100%;padding:11px" onclick="confirmOtp()">تأكيد الرمز</button>\n        <button type="button" class="btn" id="btnResendOtp" style="width:100%;padding:10px;margin-top:8px" onclick="resendOtp()">إعادة إرسال الرمز</button>\n        <button type="button" class="btn" style="width:100%;padding:10px;margin-top:8px" onclick="switchAuthMode(\'login\')">رجوع</button>\n      </div>\n\n      <div id="authMsg" class="alert err" style="display:none"></div>\n    </div>\n  </div>\n</section>\n\n<!-- ================= HEADER ================= -->\n<header id="topBar">\n  <div class="wrap nav-row">\n    <div class="brand-mark" onclick="switchSection(\'home\')"><span class="brand-monogram">د</span> الدشاش استور</div>\n    <div class="nav-right">\n      <button type="button" class="btn icon-btn" title="طلباتي" aria-label="طلباتي" onclick="openOrdersDrawer()">📦</button>\n      <button type="button" class="btn ghost-brass icon-btn" title="محفظتك في المتجر" aria-label="محفظتك في المتجر" onclick="openWalletModal()">👛</button>\n      <button type="button" class="btn brass sm" style="padding:8px 13px" title="الباقة المختارة" aria-label="الباقة المختارة" onclick="openCheckoutModal()">💎 <span id="pickedLabel">لم تُختر</span></button>\n      <button type="button" class="btn danger-soft icon-btn" title="خروج" aria-label="خروج" onclick="logoutSession()">🚪</button>\n    </div>\n  </div>\n  <div class="subnav">\n    <div class="wrap subnav-inner">\n      <button type="button" class="tab-link active" data-tab="home" onclick="switchSection(\'home\')">🏠 الرئيسية</button>\n      <button type="button" class="tab-link" data-tab="superlive" onclick="switchSection(\'superlive\')">💎 شحن SuperLive <span class="pill-tag live">متاح</span></button>\n      <button type="button" class="tab-link" data-tab="upcoming" onclick="switchSection(\'upcoming\')">✦ برامج جديدة <span class="pill-tag soon">قريباً</span></button>\n    </div>\n  </div>\n</header>\n\n<!-- ================= MAIN STOREFRONT ================= -->\n<main id="shop" class="wrap">\n\n  <!-- HOME / PROGRAMS HUB -->\n  <div id="view-home">\n    <div class="hero-card">\n      <div>\n        <div class="eyebrow">المتجر الرئيسي</div>\n        <h1>اختر القسم <span>المراد شحنه</span></h1>\n        <p>تصفح البرامج المتاحة داخل المتجر؛ قسم <strong>SuperLive</strong> جاهز للشحن الفوري، ومع التوسعات القادمة ستظهر البرامج الجديدة هنا مباشرة.</p>\n      </div>\n      <div class="hero-meta">\n        <div class="muted" style="font-weight:700">الدفع المعتمد</div>\n        <div class="big" style="margin:5px 0">InstaPay · Cash</div>\n        <div class="muted">أو من رصيد المحفظة</div>\n      </div>\n    </div>\n\n    <div class="sec-head">\n      <h3>برامج المتجر</h3>\n      <span class="muted">اختر قسماً للبدء</span>\n    </div>\n    <div class="apps-grid" id="appsHubGrid"></div>\n\n    <div class="sec-head">\n      <h3>حسابات التحويل</h3>\n      <span class="muted">الدفع المسبق</span>\n    </div>\n    <div class="pay-row" id="homePayChannelsGrid"></div>\n  </div>\n\n  <!-- SUPERLIVE TAB -->\n  <div id="view-superlive" style="display:none">\n    <div style="margin-bottom:14px">\n      <button type="button" class="btn sm" onclick="switchSection(\'home\')">← جميع البرامج</button>\n    </div>\n\n    <div class="hero-card">\n      <div>\n        <div class="eyebrow">SuperLive</div>\n        <h2>باقات شحن <span>SuperLive</span></h2>\n        <p>اختر الباقة المناسبة، ادفع عبر التحويل المباشر أو من رصيد محفظتك، وأدخل SuperLive ID لإتمام الطلب.</p>\n      </div>\n      <div class="hero-meta">\n        <div class="muted" style="font-weight:700">العملة</div>\n        <div class="big" style="margin:5px 0">COINS</div>\n        <div class="muted">شحن مباشر</div>\n      </div>\n    </div>\n\n    <div class="steps-row">\n      <div class="step-item">\n        <div class="step-idx">01</div>\n        <div><div style="font-weight:800;font-size:13.5px">حوّل أو استخدم محفظتك</div><div class="muted">إنستاباي، فودافون كاش، أو رصيد المحفظة</div></div>\n      </div>\n      <div class="step-item">\n        <div class="step-idx">02</div>\n        <div><div style="font-weight:800;font-size:13.5px">اختر الباقة والـ ID</div><div class="muted">تأكيد بيانات الحساب بدقة</div></div>\n      </div>\n      <div class="step-item">\n        <div class="step-idx">03</div>\n        <div><div style="font-weight:800;font-size:13.5px">تابع حالة الطلب</div><div class="muted">من سجل طلباتك في أي وقت</div></div>\n      </div>\n    </div>\n\n    <div class="sec-head">\n      <h3>أرقام التحويل</h3>\n      <span class="muted">نسخ فوري</span>\n    </div>\n    <div class="pay-row" id="payChannelsGrid"></div>\n\n    <div class="sec-head">\n      <h3>الباقات</h3>\n      <span class="muted" id="pkgSourceHint">الأسعار بالجنيه المصري</span>\n    </div>\n    <div class="filter-bar">\n      <div class="tier-pills">\n        <button type="button" class="pill-btn active" onclick="filterTier(\'all\',this)">الكل</button>\n        <button type="button" class="pill-btn" onclick="filterTier(\'offer1\',this)">العرض الأول</button>\n        <button type="button" class="pill-btn" onclick="filterTier(\'offer2\',this)">العرض الثاني</button>\n        <button type="button" class="pill-btn" onclick="filterTier(\'offer3\',this)">العرض الثالث</button>\n      </div>\n      <input class="search-box" id="pkgSearch" type="search" placeholder="بحث بالكوينز أو السعر..." oninput="renderPkgList()">\n    </div>\n\n    <div class="pkg-grid" id="pkgGrid">\n      <div class="muted" style="grid-column:1/-1;padding:24px;text-align:center">جاري تحميل الباقات...</div>\n    </div>\n  </div>\n\n  <!-- UPCOMING PROGRAMS TAB -->\n  <div id="view-upcoming" style="display:none">\n    <div class="hero-card" style="justify-content:center;text-align:center;padding:44px 24px">\n      <div>\n        <div class="eyebrow" style="justify-content:center">تحديثات قادمة</div>\n        <h2>برامج جديدة قيد الإضافة</h2>\n        <p style="margin:0 auto 18px">نعمل على إضافة أقسام وبرامج جديدة داخل المتجر بنفس آلية الشحن السريع.</p>\n        <button type="button" class="btn brass" onclick="switchSection(\'superlive\')">الانتقال إلى SuperLive</button>\n      </div>\n    </div>\n  </div>\n\n</main>\n\n<footer id="foot">\n  <div class="wrap foot-inner">\n    <span>الدشاش استور</span>\n    <span>© 2026</span>\n  </div>\n</footer>\n\n<!-- ================= CHECKOUT MODAL ================= -->\n<div class="modal-bg" id="checkoutModal">\n  <div class="modal-box">\n    <div class="modal-hdr">\n      <h3>إتمام طلب الشحن</h3>\n      <button type="button" class="x-btn" onclick="closeModals()">✕</button>\n    </div>\n    <div id="checkoutSummary" style="margin-bottom:14px"></div>\n    <form id="checkoutForm">\n      <div class="field">\n        <label for="cName">الاسم بالكامل</label>\n        <input id="cName" required maxlength="100" placeholder="اسمك">\n      </div>\n      <div class="field">\n        <label for="cPhone">رقم الموبايل</label>\n        <input id="cPhone" required maxlength="30" inputmode="tel" dir="ltr" placeholder="01xxxxxxxxx">\n      </div>\n      <div class="field">\n        <label for="cLiveId">SuperLive ID</label>\n        <input id="cLiveId" required maxlength="60" dir="ltr" placeholder="معرّف الحساب في SuperLive">\n      </div>\n      <div class="field">\n        <label>طريقة الدفع</label>\n        <label class="choice-row">\n          <input type="radio" name="paySource" value="transfer" checked onchange="toggleCheckoutPayMode()">\n          تحويل مباشر + إرفاق إيصال\n        </label>\n        <label class="choice-row">\n          <input type="radio" name="paySource" value="wallet" onchange="toggleCheckoutPayMode()">\n          رصيد المحفظة (<span id="checkoutWalletBal">0.00 ج.م</span>)\n        </label>\n      </div>\n      <div id="transferFieldsGroup">\n        <div class="field">\n          <label>الحساب المحوّل إليه</label>\n          <div id="paymentRadios"></div>\n        </div>\n        <div class="field">\n          <label for="cProof">صورة إثبات الدفع (JPG / PNG / WEBP — حد أقصى 5MB)</label>\n          <input id="cProof" type="file" accept="image/jpeg,image/png,image/webp" required>\n          <img id="cPreview" class="proof-thumb" alt="معاينة الإيصال">\n        </div>\n      </div>\n      <button type="submit" class="btn brass" id="cSubmit" style="width:100%;padding:11px">تأكيد الطلب</button>\n    </form>\n    <div id="checkoutDone"></div>\n  </div>\n</div>\n\n<!-- ================= WALLET MODAL ================= -->\n<div class="modal-bg" id="walletModal">\n  <div class="modal-box">\n    <div class="modal-hdr">\n      <h3>محفظتك في المتجر</h3>\n      <button type="button" class="x-btn" onclick="closeModals()">✕</button>\n    </div>\n\n    <div class="wallet-banner">\n      <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap">\n        <div>\n          <div class="muted" style="font-weight:700">الرصيد المتاح</div>\n          <div class="wallet-bal" id="walletBalanceText">0.00 ج.م</div>\n          <div class="muted" id="walletUserEmail" style="direction:ltr;text-align:right"></div>\n        </div>\n        <button type="button" class="btn brass sm" onclick="toggleDepositForm()">+ إيداع رصيد</button>\n      </div>\n    </div>\n\n    <form id="walletDepositForm" style="display:none;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius-md);padding:15px;margin-bottom:16px">\n      <div style="font-weight:800;font-size:14.5px;margin-bottom:10px">طلب إضافة رصيد للمحفظة</div>\n      <div class="field">\n        <label for="dAmount">المبلغ (ج.م)</label>\n        <input id="dAmount" type="number" min="1" step="0.01" required placeholder="مثال: 250">\n      </div>\n      <div class="field">\n        <label>وسيلة التحويل</label>\n        <div id="depositPaymentRadios"></div>\n      </div>\n      <div class="field">\n        <label for="dProof">صورة إثبات التحويل (JPG / PNG / WEBP — حد أقصى 5MB)</label>\n        <input id="dProof" type="file" accept="image/jpeg,image/png,image/webp" required>\n      </div>\n      <button type="submit" class="btn brass" id="dSubmit" style="width:100%;padding:10px">إرسال طلب الإيداع</button>\n      <div id="depositMsg"></div>\n    </form>\n\n    <div class="sec-head" style="margin-top:0">\n      <h3 style="font-size:15px">أرقام التحويل</h3>\n      <span class="muted">نسخ</span>\n    </div>\n    <div id="walletChannelsBox" style="margin-bottom:14px"></div>\n\n    <div class="sec-head" style="margin-top:4px">\n      <h3 style="font-size:15px">سجل المحفظة</h3>\n      <span class="muted" id="walletTxCount"></span>\n    </div>\n    <div id="walletHistoryBox" style="margin-bottom:14px">جاري التحميل...</div>\n\n    <div style="display:flex;gap:8px;flex-wrap:wrap">\n      <button type="button" class="btn brass" style="flex:1" onclick="closeModals(); switchSection(\'superlive\')">باقات SuperLive</button>\n      <button type="button" class="btn" onclick="closeModals(); openOrdersDrawer()">سجل الطلبات</button>\n    </div>\n  </div>\n</div>\n\n<!-- ================= MY ORDERS MODAL ================= -->\n<div class="modal-bg" id="myOrdersModal">\n  <div class="modal-box">\n    <div class="modal-hdr">\n      <h3>طلباتي</h3>\n      <button type="button" class="x-btn" onclick="closeModals()">✕</button>\n    </div>\n    <div id="myOrdersList">جاري التحميل...</div>\n  </div>\n</div>\n\n<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.min.js"></script>\n<script>\nconst SUPABASE_URL = "https://etdegfytfcfwuorexctj.supabase.co";\nconst SUPABASE_KEY = "sb_publishable_NP_1OLXEN0_f398DthKnGA_725B_IMf";\nconst PROOFS_BUCKET = "payment-proofs";\n\nconst DEFAULT_CHANNELS = [\n  { label: "إنستاباي (InstaPay)", number: "01119409694" },\n  { label: "فودافون كاش (Vodafone Cash)", number: "01011496149" }\n];\n\nfunction getChannels() {\n  try {\n    const saved = JSON.parse(localStorage.getItem("eldashash_channels_v1") || "null");\n    if (Array.isArray(saved) && saved.length) return saved;\n  } catch {}\n  return DEFAULT_CHANNELS;\n}\n\nconst STORE_APPS = [\n  {\n    id: "superlive",\n    name: "شحن SuperLive",\n    icon: "💎",\n    status: "ready",\n    badge: "متاح",\n    desc: "باقات شحن كوينز SuperLive بالمعرّف مع خيارات دفع متعددة.",\n    btn: "دخول القسم"\n  },\n  {\n    id: "upcoming",\n    name: "برامج جديدة",\n    icon: "✦",\n    status: "soon",\n    badge: "قريباً",\n    desc: "توسعات جديدة لتطبيقات وخدمات إضافية داخل المتجر.",\n    btn: "قريباً"\n  },\n  {\n    id: "upcoming",\n    name: "بطاقات وأكواد",\n    icon: "◈",\n    status: "soon",\n    badge: "قريباً",\n    desc: "إضافة بطاقات الشحن الرقمية والخدمات الإضافية قريباً.",\n    btn: "قريباً"\n  }\n];\n\nconst TIERS = { offer1: "العرض الأول", offer2: "العرض الثاني", offer3: "العرض الثالث" };\nconst STATUS_AR = { pending: "قيد المراجعة", paid: "مؤكد", shipped: "تم الشحن", rejected: "مرفوض" };\nconst STATUS_CLS = { pending: "st-pending", paid: "st-paid", shipped: "st-shipped", rejected: "st-rejected" };\n\nlet sb = (window.supabase && typeof window.supabase.createClient === "function")\n  ? window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY)\n  : null;\n\nlet allPackages = [];\nlet selectedPkg = null;\nlet currentTier = "all";\nlet otpEmail = "";\nlet otpFlow = "signup";\nlet authBusy = false;\n\nconst fmt = n => Number(n).toLocaleString("en-US");\nconst esc = s => String(s ?? "").replace(/[&<>"\']/g, m => ({ "&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;","\'":"&#39;" }[m]));\n\nfunction ensureClient() {\n  if (!sb && window.supabase && typeof window.supabase.createClient === "function") {\n    sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY);\n  }\n  return sb;\n}\n\nfunction switchSection(sec) {\n  ["home", "superlive", "upcoming"].forEach(k => {\n    const el = document.getElementById("view-" + k);\n    if (el) el.style.display = (k === sec) ? "block" : "none";\n  });\n  document.querySelectorAll(".tab-link").forEach(b => b.classList.toggle("active", b.dataset.tab === sec));\n  window.scrollTo({ top: 0, behavior: "smooth" });\n}\n\nfunction renderAppsHub() {\n  document.getElementById("appsHubGrid").innerHTML = STORE_APPS.map(a => {\n    const isReady = a.status === "ready";\n    return `\n      <div class="app-tile ${isReady ? "ready" : ""}">\n        <div>\n          <div class="app-tile-top" style="margin-bottom:14px">\n            <div class="app-badge-icon">${a.icon}</div>\n            <span class="status-txt ${isReady ? "ready" : "soon"}">${esc(a.badge)}</span>\n          </div>\n          <h4>${esc(a.name)}</h4>\n          <p>${esc(a.desc)}</p>\n        </div>\n        <div>\n          ${isReady\n            ? `<button type="button" class="btn brass" style="width:100%" onclick="switchSection(\'${a.id}\')">${esc(a.btn)}</button>`\n            : `<button type="button" class="btn" style="width:100%" onclick="toast(\'هذا القسم قيد التجهيز وسيتم إضافته قريباً\')">${esc(a.btn)}</button>`\n          }\n        </div>\n      </div>\n    `;\n  }).join("");\n}\n\nfunction renderPaymentUi() {\n  const channels = getChannels();\n  const cards = channels.map(ch => `\n    <div class="pay-card">\n      <div>\n        <div style="font-weight:700;font-size:13px;color:var(--ink-soft)">${esc(ch.label)}</div>\n        <div class="pay-num">${esc(ch.number)}</div>\n      </div>\n      <button type="button" class="btn ghost-brass sm" onclick="copyNum(\'${esc(ch.number)}\')">نسخ</button>\n    </div>\n  `).join("");\n\n  document.getElementById("payChannelsGrid").innerHTML = cards;\n  document.getElementById("homePayChannelsGrid").innerHTML = cards;\n\n  const radiosHtml = channels.map((ch, i) => `\n    <label class="choice-row">\n      <input type="radio" name="payMethod" value="${esc(ch.label)}" ${i === 0 ? "checked" : ""}>\n      ${esc(ch.label)} — <span dir="ltr">${esc(ch.number)}</span>\n    </label>\n  `).join("");\n  document.getElementById("paymentRadios").innerHTML = radiosHtml;\n\n  const depRadios = document.getElementById("depositPaymentRadios");\n  if (depRadios) {\n    depRadios.innerHTML = channels.map((ch, i) => `\n      <label class="choice-row">\n        <input type="radio" name="depPayMethod" value="${esc(ch.label)}" ${i === 0 ? "checked" : ""}>\n        ${esc(ch.label)} — <span dir="ltr">${esc(ch.number)}</span>\n      </label>\n    `).join("");\n  }\n}\n\nfunction toast(msg) {\n  const box = document.getElementById("toastBox");\n  const d = document.createElement("div");\n  d.className = "toast";\n  d.textContent = msg;\n  box.appendChild(d);\n  setTimeout(() => d.remove(), 2700);\n}\n\nasync function copyNum(val) {\n  try { await navigator.clipboard.writeText(val); }\n  catch {\n    const t = document.createElement("textarea");\n    t.value = val; document.body.appendChild(t); t.select();\n    document.execCommand("copy"); t.remove();\n  }\n  toast("تم النسخ: " + val);\n}\n\nfunction showMsg(msg, ok = false) {\n  const el = document.getElementById("authMsg");\n  el.style.display = "block";\n  el.className = ok ? "alert ok" : "alert err";\n  el.textContent = msg;\n}\nfunction hideMsg() { document.getElementById("authMsg").style.display = "none"; }\n\nfunction switchAuthMode(mode) {\n  hideMsg();\n  document.getElementById("otpSection").style.display = "none";\n  document.getElementById("modeSwitch").style.display = "grid";\n  const login = mode === "login";\n  document.getElementById("btnTabLogin").classList.toggle("active", login);\n  document.getElementById("btnTabSignup").classList.toggle("active", !login);\n  document.getElementById("loginForm").style.display = login ? "block" : "none";\n  document.getElementById("signupForm").style.display = login ? "none" : "block";\n}\n\nfunction openOtpBox(email, flow, noticeText) {\n  otpEmail = email.trim().toLowerCase();\n  otpFlow = flow;\n  document.getElementById("loginForm").style.display = "none";\n  document.getElementById("signupForm").style.display = "none";\n  document.getElementById("modeSwitch").style.display = "none";\n  document.getElementById("otpSection").style.display = "block";\n  document.getElementById("otpTargetEmail").textContent = otpEmail;\n  document.getElementById("otpInput").value = "";\n  document.getElementById("otpInput").focus();\n  showMsg(noticeText || "تم إرسال رمز التحقق (6 أرقام) إلى بريدك الإلكتروني.", true);\n}\n\nfunction showAuthView() {\n  closeModals();\n  document.getElementById("authScreen").style.display = "grid";\n  document.getElementById("topBar").classList.remove("show");\n  document.getElementById("shop").classList.remove("show");\n  document.getElementById("foot").classList.remove("show");\n  switchAuthMode("login");\n}\n\nfunction openShopView() {\n  closeModals();\n  document.getElementById("authScreen").style.display = "none";\n  document.getElementById("topBar").classList.add("show");\n  document.getElementById("shop").classList.add("show");\n  document.getElementById("foot").classList.add("show");\n}\n\nasync function syncSession() {\n  const client = ensureClient();\n  if (!client) { showAuthView(); return; }\n  const { data: { session } } = await client.auth.getSession();\n  if (!session) { showAuthView(); return; }\n  if (session.user.user_metadata?.full_name && !document.getElementById("cName").value) {\n    document.getElementById("cName").value = session.user.user_metadata.full_name;\n  }\n  openShopView();\n}\n\ndocument.getElementById("loginForm").addEventListener("submit", async e => {\n  e.preventDefault();\n  if (authBusy) return;\n  hideMsg();\n  const client = ensureClient();\n  if (!client) { showMsg("تعذر تهيئة الاتصال."); return; }\n  authBusy = true;\n  const btn = document.getElementById("lSubmit");\n  btn.disabled = true;\n  try {\n    const email = document.getElementById("lEmail").value.trim().toLowerCase();\n    const { error } = await client.auth.signInWithPassword({ email, password: document.getElementById("lPass").value });\n    if (error) { showMsg(error.message); return; }\n    await syncSession();\n    toast("تم تسجيل الدخول");\n  } catch (err) {\n    showMsg(err?.message || "تعذر الاتصال.");\n  } finally {\n    authBusy = false; btn.disabled = false;\n  }\n});\n\nasync function startEmailOtpLogin() {\n  if (authBusy) return;\n  hideMsg();\n  const client = ensureClient();\n  if (!client) { showMsg("تعذر تهيئة الاتصال."); return; }\n  const email = document.getElementById("lEmail").value.trim().toLowerCase();\n  if (!email) { showMsg("أدخل البريد الإلكتروني أولاً."); document.getElementById("lEmail").focus(); return; }\n  authBusy = true;\n  const btn = document.getElementById("btnOtpLogin");\n  btn.disabled = true;\n  try {\n    const { error } = await client.auth.signInWithOtp({ email, options: { shouldCreateUser: true } });\n    if (error) { showMsg(error.message); return; }\n    openOtpBox(email, "email", "تم إرسال رمز OTP المكوّن من 6 أرقام إلى بريدك الإلكتروني.");\n  } catch (err) {\n    showMsg(err?.message || "تعذر إرسال الرمز.");\n  } finally {\n    authBusy = false; btn.disabled = false;\n  }\n}\n\ndocument.getElementById("signupForm").addEventListener("submit", async e => {\n  e.preventDefault();\n  if (authBusy) return;\n  hideMsg();\n  const client = ensureClient();\n  if (!client) { showMsg("تعذر تهيئة الاتصال."); return; }\n\n  const name = document.getElementById("sName").value.trim();\n  const email = document.getElementById("sEmail").value.trim().toLowerCase();\n  const p1 = document.getElementById("sPass").value;\n  const p2 = document.getElementById("sPass2").value;\n\n  if (!email) { showMsg("أدخل البريد الإلكتروني."); return; }\n  if (p1.length < 6) { showMsg("كلمة المرور 6 أحرف على الأقل."); return; }\n  if (p1 !== p2) { showMsg("كلمتا المرور غير متطابقتين."); return; }\n\n  authBusy = true;\n  const btn = document.getElementById("sSubmit");\n  btn.disabled = true;\n  try {\n    const { data, error: signUpErr } = await client.auth.signUp({\n      email, password: p1, options: { data: { full_name: name } }\n    });\n    if (signUpErr && signUpErr.message.toLowerCase().includes("already registered")) {\n      showMsg("هذا البريد الإلكتروني مسجل بالفعل! انتقل إلى تبويب (دخول).");\n      return;\n    }\n    if (data?.user && Array.isArray(data.user.identities) && data.user.identities.length === 0) {\n      showMsg("هذا البريد الإلكتروني مسجل بالفعل! انتقل إلى تبويب (دخول).");\n      return;\n    }\n    const { error: otpErr } = await client.auth.signInWithOtp({\n      email, options: { shouldCreateUser: true, data: { full_name: name } }\n    });\n    if (otpErr) { showMsg(otpErr.message); return; }\n    openOtpBox(email, "email", "تم إرسال رمز التحقق (6 أرقام) إلى بريدك الإلكتروني.");\n  } catch (err) {\n    showMsg(err?.message || "تعذر إرسال الرمز.");\n  } finally {\n    authBusy = false; btn.disabled = false;\n  }\n});\n\nasync function confirmOtp() {\n  if (authBusy) return;\n  hideMsg();\n  const client = ensureClient();\n  if (!client) return;\n  const email = (otpEmail || document.getElementById("sEmail").value || document.getElementById("lEmail").value || "").trim().toLowerCase();\n  const token = document.getElementById("otpInput").value.trim();\n  if (!email) { showMsg("البريد الإلكتروني غير محدد."); return; }\n  if (!/^\\d{6}$/.test(token)) { showMsg("أدخل الرمز المكوّن من 6 أرقام."); return; }\n\n  authBusy = true;\n  const btn = document.getElementById("btnConfirmOtp");\n  btn.disabled = true;\n  try {\n    const verifyType = otpFlow === "email" ? "email" : "signup";\n    let { error } = await client.auth.verifyOtp({ email, token, type: verifyType });\n    if (error && verifyType !== "email") {\n      const retry = await client.auth.verifyOtp({ email, token, type: "email" });\n      if (!retry.error) error = null;\n    }\n    if (error) { showMsg(error.message); return; }\n    await syncSession();\n    toast("تم التحقق بنجاح");\n  } catch (err) {\n    showMsg(err?.message || "تعذر التحقق.");\n  } finally {\n    authBusy = false; btn.disabled = false;\n  }\n}\n\nasync function resendOtp() {\n  if (authBusy) return;\n  hideMsg();\n  const client = ensureClient();\n  if (!client) return;\n  const email = (otpEmail || document.getElementById("sEmail").value || document.getElementById("lEmail").value || "").trim().toLowerCase();\n  if (!email) { showMsg("أدخل البريد الإلكتروني أولاً."); return; }\n  authBusy = true;\n  const btn = document.getElementById("btnResendOtp");\n  btn.disabled = true;\n  try {\n    const { error } = otpFlow === "email"\n      ? await client.auth.signInWithOtp({ email, options: { shouldCreateUser: true } })\n      : await client.auth.resend({ type: "signup", email });\n    if (error) showMsg(error.message);\n    else showMsg("تم إعادة إرسال الرمز (6 أرقام).", true);\n  } catch (err) {\n    showMsg(err?.message || "تعذر إعادة الإرسال.");\n  } finally {\n    authBusy = false; btn.disabled = false;\n  }\n}\n\nasync function logoutSession() {\n  if (sb) await sb.auth.signOut();\n  showAuthView();\n}\n\nfunction fallbackPackages() {\n  return [\n    [100,222,1],[150,333,1],[200,444,1],[300,667,1],[400,889,1],[500,1111,1],\n    [600,1333,1],[1000,2222,1],[1500,3333,1],[2000,4444,1],[2500,5556,1],[3000,6667,1],\n    [3500,7778,1],[4000,8889,1],[5000,11111,1],[6000,13333,1],[7000,15556,1],[8000,17778,1],\n    [10000,22222,1],[12000,26667,1],[14000,31111,1],[16000,35556,1],[17820,39600,1],\n    [17874,41375,2],[20000,46301,2],[25000,57870,2],[30000,69444,2],[35000,81019,2],\n    [41580,96250,2],[41634,97146,3],[50000,116667,3]\n  ].map((r, i) => ({ id: i + 1, price_egp: r[0], coins: r[1], offer_group: "offer" + r[2] }));\n}\n\nasync function loadPkgData() {\n  const client = ensureClient();\n  if (!client) { allPackages = fallbackPackages(); renderPkgList(); return; }\n  try {\n    const { data, error } = await client\n      .from("packages")\n      .select("id,price_egp,coins,offer_group")\n      .eq("active", true)\n      .order("price_egp");\n    if (!error && data && data.length) {\n      allPackages = data;\n      document.getElementById("pkgSourceHint").textContent = "محدّث من قاعدة البيانات";\n    } else {\n      allPackages = fallbackPackages();\n      document.getElementById("pkgSourceHint").textContent = "الأسعار بالجنيه المصري";\n    }\n  } catch {\n    allPackages = fallbackPackages();\n  }\n  renderPkgList();\n}\n\nfunction filterTier(tier, el) {\n  currentTier = tier;\n  document.querySelectorAll(".pill-btn").forEach(c => c.classList.remove("active"));\n  el.classList.add("active");\n  renderPkgList();\n}\n\nfunction renderPkgList() {\n  const q = (document.getElementById("pkgSearch").value || "").trim().toLowerCase();\n  const list = allPackages.filter(p => {\n    const okTier = currentTier === "all" || p.offer_group === currentTier;\n    const okQ = !q || String(p.coins).includes(q) || String(p.price_egp).includes(q);\n    return okTier && okQ;\n  });\n  const grid = document.getElementById("pkgGrid");\n  if (!list.length) {\n    grid.innerHTML = \'<div class="muted" style="grid-column:1/-1;padding:28px;text-align:center">لا توجد باقات مطابقة</div>\';\n    return;\n  }\n  grid.innerHTML = list.map(p => {\n    const featured = p.offer_group === "offer3" || Number(p.price_egp) >= 20000;\n    return `\n      <div class="pkg-item ${featured ? "featured-tier" : ""}">\n        <div>\n          <div class="pkg-head">\n            <span class="pkg-code">SUPERLIVE</span>\n            <span class="pkg-tier">${esc(TIERS[p.offer_group] || "باقة")}</span>\n          </div>\n          <div class="pkg-amount">${fmt(p.coins)} <span style="font-size:13px;color:var(--muted);font-weight:700">كوين</span></div>\n        </div>\n        <div>\n          <div class="pkg-price-line">\n            <span class="muted" style="font-size:12px">السعر</span>\n            <span class="pkg-price-val">${fmt(p.price_egp)} ج.م</span>\n          </div>\n          <button type="button" class="btn ${featured ? "brass" : ""} sm" style="width:100%;padding:9px" onclick="selectPkg(\'${p.id}\')">اختيار الباقة</button>\n        </div>\n      </div>\n    `;\n  }).join("");\n}\n\nfunction selectPkg(id) {\n  selectedPkg = allPackages.find(p => String(p.id) === String(id));\n  if (!selectedPkg) return;\n  closeModals();\n  document.getElementById("pickedLabel").textContent = `${fmt(selectedPkg.coins)}`;\n  document.getElementById("checkoutSummary").innerHTML = `\n    <div class="list-row" style="background:var(--bg);padding:12px 14px;border-radius:10px;border:1px solid var(--line-strong)">\n      <div><b>${fmt(selectedPkg.coins)} كوين</b> <span class="muted">· SuperLive</span></div>\n      <div style="color:var(--brass-bright);font-weight:900">${fmt(selectedPkg.price_egp)} ج.م</div>\n    </div>\n  `;\n  document.getElementById("checkoutDone").innerHTML = "";\n  document.getElementById("checkoutForm").style.display = "block";\n  document.getElementById("checkoutModal").classList.add("open");\n  toggleCheckoutPayMode();\n\n  const client = ensureClient();\n  if (client) {\n    client.auth.getUser().then(async ({ data: { user } }) => {\n      if (!user) return;\n      const b = await fetchUserWalletBalance(client, user.id);\n      const el = document.getElementById("checkoutWalletBal");\n      if (el) el.textContent = `${fmt(b.toFixed(2))} ج.م`;\n    });\n  }\n}\n\nfunction openCheckoutModal() {\n  if (!selectedPkg) {\n    switchSection("superlive");\n    toast("اختر باقة أولاً");\n    return;\n  }\n  closeModals();\n  document.getElementById("checkoutModal").classList.add("open");\n}\n\nfunction closeModals() {\n  document.querySelectorAll(".modal-bg").forEach(m => m.classList.remove("open"));\n}\n\nfunction toggleCheckoutPayMode() {\n  const mode = document.querySelector(\'input[name="paySource"]:checked\')?.value || "transfer";\n  const isWallet = mode === "wallet";\n  document.getElementById("transferFieldsGroup").style.display = isWallet ? "none" : "block";\n  document.getElementById("cProof").required = !isWallet;\n}\n\nasync function fetchUserWalletBalance(client, userId) {\n  try {\n    const { data, error } = await client.from("wallets").select("balance").eq("user_id", userId).maybeSingle();\n    if (!error && data && typeof data.balance !== "undefined") return Number(data.balance || 0);\n  } catch {}\n  return 0;\n}\n\ndocument.getElementById("cProof").addEventListener("change", e => {\n  const file = e.target.files[0];\n  const img = document.getElementById("cPreview");\n  if (!file || !file.type.startsWith("image/")) { img.style.display = "none"; return; }\n  img.src = URL.createObjectURL(file);\n  img.style.display = "block";\n});\n\ndocument.getElementById("checkoutForm").addEventListener("submit", async e => {\n  e.preventDefault();\n  const client = ensureClient();\n  if (!client || !selectedPkg) return;\n\n  const paySource = document.querySelector(\'input[name="paySource"]:checked\')?.value || "transfer";\n  const btn = document.getElementById("cSubmit");\n  btn.disabled = true;\n\n  try {\n    const { data: { user } } = await client.auth.getUser();\n    if (!user) throw new Error("يجب تسجيل الدخول أولاً");\n\n    const customerName = document.getElementById("cName").value.trim();\n    const phone = document.getElementById("cPhone").value.trim();\n    const superliveId = document.getElementById("cLiveId").value.trim();\n    const pkgId = typeof selectedPkg.id === "number" ? selectedPkg.id : null;\n\n    if (paySource === "wallet") {\n      const priceNum = Number(selectedPkg.price_egp);\n      const coinsNum = Number(selectedPkg.coins);\n      const curBal = await fetchUserWalletBalance(client, user.id);\n      if (curBal < priceNum) {\n        throw new Error("رصيد المحفظة غير كافٍ لإتمام هذه الباقة.");\n      }\n\n      let orderRef = "";\n      const { data: rpcOrderId, error: rpcErr } = await client.rpc("pay_order_from_wallet", {\n        p_customer_name: customerName,\n        p_phone: phone,\n        p_superlive_id: superliveId,\n        p_package_id: pkgId,\n        p_package_price: priceNum,\n        p_coins: coinsNum\n      });\n\n      if (!rpcErr) {\n        orderRef = String(rpcOrderId || "");\n      } else {\n        // fallback مباشر لو الدالة لم تُحدّث بعد في SQL Editor\n        const nextBal = Number((curBal - priceNum).toFixed(2));\n        const { error: balErr } = await client\n          .from("wallets")\n          .update({ balance: nextBal, updated_at: new Date().toISOString() })\n          .eq("user_id", user.id);\n        if (balErr) throw balErr;\n\n        const { data: insertedOrder, error: ordErr } = await client\n          .from("orders")\n          .insert({\n            user_id: user.id,\n            customer_name: customerName,\n            phone,\n            superlive_id: superliveId,\n            package_id: pkgId,\n            package_price: priceNum,\n            coins: coinsNum,\n            payment_method: "رصيد المحفظة",\n            status: "paid",\n            payment_proof: "wallet_balance"\n          })\n          .select("id")\n          .single();\n        if (ordErr) throw ordErr;\n\n        await client.from("wallet_transactions").insert({\n          user_id: user.id,\n          tx_type: "order_debit",\n          amount: -priceNum,\n          description: `شراء باقة ${coinsNum} كوين (SuperLive)`\n        }).catch(() => {});\n\n        orderRef = String(insertedOrder?.id || "");\n      }\n\n      const updatedBal = await fetchUserWalletBalance(client, user.id);\n      const balEl = document.getElementById("checkoutWalletBal");\n      if (balEl) balEl.textContent = `${fmt(updatedBal.toFixed(2))} ج.م`;\n      const wBalEl = document.getElementById("walletBalanceText");\n      if (wBalEl) wBalEl.textContent = `${fmt(updatedBal.toFixed(2))} ج.م`;\n\n      document.getElementById("checkoutForm").style.display = "none";\n      const refLabel = orderRef ? `#${esc(orderRef)}` : "مؤكد";\n      document.getElementById("checkoutDone").innerHTML = `\n        <div class="alert ok">\n          تم خصم <b>${fmt(priceNum)} ج.م</b> من رصيد المحفظة وإضافة الطلب إلى قائمة طلباتك (${refLabel}).\n          <div style="margin-top:10px">\n            <button type="button" class="btn brass sm" onclick="openOrdersDrawer()">عرض قائمة طلباتي</button>\n          </div>\n        </div>\n      `;\n      toast("تم الخصم من المحفظة وإضافة الطلب");\n      return;\n    }\n\n    const file = document.getElementById("cProof").files[0];\n    const extMap = { "image/jpeg": "jpg", "image/png": "png", "image/webp": "webp" };\n    if (!file || !extMap[file.type] || file.size > 5 * 1024 * 1024) {\n      toast("ارفع صورة JPG أو PNG أو WEBP بحد أقصى 5MB");\n      return;\n    }\n\n    const ref = crypto.randomUUID();\n    const storagePath = `${user.id}/${ref}.${extMap[file.type]}`;\n    const { error: upErr } = await client.storage.from(PROOFS_BUCKET).upload(storagePath, file, {\n      contentType: file.type, upsert: false\n    });\n    if (upErr) throw upErr;\n\n    const { error: insErr } = await client.from("orders").insert({\n      user_id: user.id,\n      customer_name: customerName,\n      phone,\n      superlive_id: superliveId,\n      package_id: pkgId,\n      package_price: selectedPkg.price_egp,\n      coins: selectedPkg.coins,\n      payment_method: document.querySelector(\'input[name="payMethod"]:checked\').value,\n      status: "pending",\n      payment_proof: storagePath\n    });\n    if (insErr) throw insErr;\n\n    document.getElementById("checkoutForm").style.display = "none";\n    document.getElementById("checkoutDone").innerHTML = `<div class="alert ok">تم إرسال طلبك بنجاح — المرجع: <b>${ref.slice(0, 8).toUpperCase()}</b></div>`;\n    toast("تم إرسال الطلب");\n  } catch (err) {\n    toast(err.message || "حدث خطأ أثناء الإرسال");\n  } finally {\n    btn.disabled = false;\n  }\n});\n\nfunction toggleDepositForm() {\n  const f = document.getElementById("walletDepositForm");\n  f.style.display = f.style.display === "none" ? "block" : "none";\n}\n\ndocument.getElementById("walletDepositForm").addEventListener("submit", async e => {\n  e.preventDefault();\n  const client = ensureClient();\n  const msgBox = document.getElementById("depositMsg");\n  msgBox.innerHTML = "";\n  if (!client) { msgBox.innerHTML = \'<div class="alert err">تعذر الاتصال.</div>\'; return; }\n\n  const amount = Number(document.getElementById("dAmount").value);\n  const file = document.getElementById("dProof").files[0];\n  const extMap = { "image/jpeg": "jpg", "image/png": "png", "image/webp": "webp" };\n\n  if (!amount || amount <= 0) { msgBox.innerHTML = \'<div class="alert err">أدخل مبلغاً صحيحاً.</div>\'; return; }\n  if (!file || !extMap[file.type] || file.size > 5 * 1024 * 1024) {\n    msgBox.innerHTML = \'<div class="alert err">ارفع صورة JPG أو PNG أو WEBP بحد أقصى 5MB.</div>\';\n    return;\n  }\n\n  const btn = document.getElementById("dSubmit");\n  btn.disabled = true;\n  try {\n    const { data: { user } } = await client.auth.getUser();\n    if (!user) throw new Error("يجب تسجيل الدخول أولاً");\n\n    const ref = crypto.randomUUID();\n    const storagePath = `${user.id}/deposits/${ref}.${extMap[file.type]}`;\n    const { error: upErr } = await client.storage.from(PROOFS_BUCKET).upload(storagePath, file, {\n      contentType: file.type, upsert: false\n    });\n    if (upErr) throw upErr;\n\n    const { error: insErr } = await client.from("wallet_deposits").insert({\n      user_id: user.id,\n      user_email: user.email || "",\n      amount,\n      payment_method: document.querySelector(\'input[name="depPayMethod"]:checked\').value,\n      proof_path: storagePath,\n      status: "pending"\n    });\n    if (insErr) throw insErr;\n\n    document.getElementById("walletDepositForm").reset();\n    document.getElementById("walletDepositForm").style.display = "none";\n    toast("تم إرسال طلب الإيداع");\n    await openWalletModal();\n  } catch (err) {\n    msgBox.innerHTML = `<div class="alert err">${esc(err.message || "تعذر إرسال الطلب.")}</div>`;\n  } finally {\n    btn.disabled = false;\n  }\n});\n\nasync function openWalletModal() {\n  const client = ensureClient();\n  closeModals();\n  renderPaymentUi();\n  document.getElementById("walletModal").classList.add("open");\n\n  const channels = getChannels();\n  document.getElementById("walletChannelsBox").innerHTML = channels.map(ch => `\n    <div class="pay-card" style="margin-bottom:8px;padding:12px 14px">\n      <div>\n        <div style="font-weight:700;font-size:13px;color:var(--ink-soft)">${esc(ch.label)}</div>\n        <div class="pay-num" style="font-size:17px">${esc(ch.number)}</div>\n      </div>\n      <button type="button" class="btn ghost-brass sm" onclick="copyNum(\'${esc(ch.number)}\')">نسخ</button>\n    </div>\n  `).join("");\n\n  const balanceEl = document.getElementById("walletBalanceText");\n  const emailEl = document.getElementById("walletUserEmail");\n  const historyEl = document.getElementById("walletHistoryBox");\n  const countEl = document.getElementById("walletTxCount");\n  balanceEl.textContent = "0.00 ج.م";\n  historyEl.innerHTML = \'<div class="muted">جاري التحميل...</div>\';\n\n  if (!client) return;\n  const { data: { user } } = await client.auth.getUser();\n  if (!user) return;\n  emailEl.textContent = user.email || "";\n\n  const bal = await fetchUserWalletBalance(client, user.id);\n  balanceEl.textContent = `${fmt(bal.toFixed(2))} ج.م`;\n\n  try {\n    const [{ data: deps }, { data: txs }] = await Promise.all([\n      client.from("wallet_deposits").select("amount,payment_method,status,admin_note,created_at").eq("user_id", user.id).order("created_at", { ascending: false }).limit(10),\n      client.from("wallet_transactions").select("tx_type,amount,description,created_at").eq("user_id", user.id).order("created_at", { ascending: false }).limit(10)\n    ]);\n\n    const items = [];\n    (txs || []).forEach(t => items.push({\n      date: t.created_at,\n      title: t.description || (t.tx_type === "admin_credit" ? "إضافة رصيد" : "حركة محفظة"),\n      amount: Number(t.amount || 0),\n      status: t.tx_type === "admin_credit" ? "مضاف" : "مخصوم"\n    }));\n    (deps || []).forEach(d => items.push({\n      date: d.created_at,\n      title: `إيداع (${d.payment_method})`,\n      amount: Number(d.amount || 0),\n      status: d.status === "approved" ? "معتمد" : (d.status === "rejected" ? "مرفوض" : "قيد المراجعة"),\n      note: d.admin_note\n    }));\n\n    items.sort((a, b) => new Date(b.date) - new Date(a.date));\n    countEl.textContent = items.length ? `${items.length}` : "";\n\n    if (!items.length) {\n      historyEl.innerHTML = \'<div class="muted" style="text-align:center;padding:12px">لا توجد حركات حتى الآن</div>\';\n      return;\n    }\n\n    historyEl.innerHTML = items.slice(0, 8).map(it => `\n      <div class="list-row">\n        <div>\n          <b>${esc(it.title)}</b><br>\n          <span class="muted">${new Date(it.date).toLocaleString("ar-EG")}</span>\n          ${it.note ? `<div style="color:var(--brass-bright);font-size:12px;margin-top:3px">${esc(it.note)}</div>` : ""}\n        </div>\n        <div style="text-align:left">\n          <div style="font-weight:900;color:${it.amount >= 0 ? "#78e0b5" : "#f3a6a3"}">${it.amount >= 0 ? "+" : ""}${fmt(it.amount.toFixed(2))} ج.م</div>\n          <span class="st-badge st-pending" style="margin-top:4px">${esc(it.status)}</span>\n        </div>\n      </div>\n    `).join("");\n  } catch {\n    historyEl.innerHTML = \'<div class="muted">شغّل ملف SQL الخاص بالمحفظة لتفعيل السجل.</div>\';\n  }\n}\n\nasync function openOrdersDrawer() {\n  const client = ensureClient();\n  if (!client) return;\n  closeModals();\n  document.getElementById("myOrdersModal").classList.add("open");\n  const { data: { user } } = await client.auth.getUser();\n  if (!user) return;\n  const { data, error } = await client\n    .from("orders")\n    .select("created_at,coins,package_price,status,admin_note,superlive_id")\n    .eq("user_id", user.id)\n    .order("created_at", { ascending: false });\n\n  const box = document.getElementById("myOrdersList");\n  if (error) { box.innerHTML = `<div class="alert err">${esc(error.message)}</div>`; return; }\n  box.innerHTML = data?.length ? data.map(o => `\n    <div class="list-row">\n      <div>\n        <b>${fmt(o.coins)} كوين</b> <span class="muted">(${fmt(o.package_price)} ج.م)</span><br>\n        <span class="muted">ID: <b style="color:var(--ink-soft)">${esc(o.superlive_id)}</b></span><br>\n        <span class="muted">${new Date(o.created_at).toLocaleString("ar-EG")}</span>\n        ${o.admin_note ? `<div style="color:var(--brass-bright);font-size:12px;margin-top:3px">ملاحظة: ${esc(o.admin_note)}</div>` : ""}\n      </div>\n      <span class="st-badge ${STATUS_CLS[o.status] || "st-pending"}">${STATUS_AR[o.status] || "غير محدد"}</span>\n    </div>\n  `).join("") : \'<div class="muted" style="text-align:center;padding:20px">لا توجد طلبات</div>\';\n}\n\nasync function startShop() {\n  renderAppsHub();\n  renderPaymentUi();\n  await loadPkgData();\n  await syncSession();\n}\n\nwindow.addEventListener("load", startShop);\n</script>\n</body>\n</html>\n', {
      headers: { "content-type": "text/html; charset=utf-8" },
    });
  },
};
